.bkq-search {
  /* re-theme with these four */
  --bkq-search-bg: oklch(98.6% 0.004 230);
  --bkq-search-ink: oklch(23% 0.025 255);
  --bkq-search-accent: oklch(54% 0.13 158);
  --bkq-search-mark: oklch(92% 0.15 102);

  --bkq-search-muted: color-mix(in oklch, var(--bkq-search-ink) 60%, var(--bkq-search-bg));
  --bkq-search-faint: color-mix(in oklch, var(--bkq-search-ink) 40%, var(--bkq-search-bg));
  --bkq-search-line: color-mix(in oklch, var(--bkq-search-ink) 11%, var(--bkq-search-bg));
  --bkq-search-card: color-mix(in oklch, white 70%, var(--bkq-search-bg));
  --bkq-search-tint: color-mix(in oklch, var(--bkq-search-accent) 9%, var(--bkq-search-bg));
  --bkq-search-ring: color-mix(in oklch, var(--bkq-search-accent) 55%, transparent);
  --bkq-search-out: cubic-bezier(.2, .8, .2, 1);
  --bkq-search-spring: linear(0, .013 .6%, .05 1.2%, .2 2.6%, .434 4.3%, .71 6.6%, .887 8.6%, 1.003 10.8%, 1.06 13%, 1.08 15.4%, 1.07 18.2%, 1.03 23%, 1.004 28.4%, .995 35.6%, 1);
  --bkq-search-gutter: clamp(16px, 5cqi, 64px);

  container-type: inline-size;
  container-name: bkq-search;
  interpolate-size: allow-keywords;
  box-sizing: border-box;
  width: 100%;
  background: var(--bkq-search-bg);
  color: var(--bkq-search-ink);
  font: 400 15px/1.55 system-ui, -apple-system, "Segoe UI", Roboto, sans-serif;
  -webkit-font-smoothing: antialiased;

  & *, & *::before, & *::after { box-sizing: border-box; }
  & :where(h2, p, kbd) { margin: 0; }
  & :where(button, input) { font: inherit; color: inherit; }
  & :focus-visible { outline: 2px solid var(--bkq-search-ring); outline-offset: 3px; border-radius: 6px; }
}

.bkq-search ::highlight(bkq-search-hit) { background-color: oklch(92% 0.15 102); color: oklch(23% 0.025 255); }
.bkq-search-mark { background: var(--bkq-search-mark); color: inherit; border-radius: 2px; box-shadow: 0 0 0 1px var(--bkq-search-mark); }

.bkq-search-in {
  display: grid;
  gap: 24px 0;
  padding: clamp(36px, 6cqi, 80px) var(--bkq-search-gutter);
  grid-template-columns: minmax(0, 1fr);
  grid-template-areas: "head" "tools" "list" "help";
  max-width: 1240px;
  margin-inline: auto;
}

.bkq-search-head { grid-area: head; display: grid; gap: 14px; }
.bkq-search-brand {
  display: flex; align-items: center; gap: 8px;
  font-size: 13px; color: var(--bkq-search-muted);
  & svg { width: 22px; height: 22px; fill: none; stroke: var(--bkq-search-accent); stroke-width: 1.6; stroke-linejoin: round; stroke-linecap: round; }
  & b { color: var(--bkq-search-ink); font-weight: 680; letter-spacing: -.01em; font-size: 14.5px; }
  & span { padding-left: 8px; border-left: 1px solid var(--bkq-search-line); }
}
.bkq-search-title {
  font-size: clamp(30px, 3.6cqi + 14px, 52px);
  line-height: 1.02;
  letter-spacing: -.035em;
  font-weight: 660;
  text-wrap: balance;
  max-width: 13ch;
}
.bkq-search-lede { color: var(--bkq-search-muted); max-width: 40ch; text-wrap: pretty; font-size: clamp(15px, .5cqi + 13px, 17px); }

.bkq-search-tools { grid-area: tools; display: grid; gap: 14px; align-content: start; }
.bkq-search-field {
  position: relative;
  display: flex; align-items: center; gap: 10px;
  height: 52px;
  padding: 0 12px 0 16px;
  border-radius: 14px;
  background: var(--bkq-search-card);
  border: 1px solid var(--bkq-search-line);
  box-shadow: 0 1px 0 color-mix(in oklch, var(--bkq-search-ink) 4%, transparent), 0 8px 24px -14px color-mix(in oklch, var(--bkq-search-ink) 30%, transparent);
  transition: border-color .2s, box-shadow .3s var(--bkq-search-out);
  cursor: text;
  & svg { width: 20px; height: 20px; flex: none; fill: none; stroke: var(--bkq-search-faint); stroke-width: 1.8; stroke-linecap: round; transition: stroke .2s; }
  & input {
    flex: 1; min-width: 0; height: 100%;
    border: 0; background: none; outline: none;
    font-size: 16px; letter-spacing: -.005em;
    &:focus-visible { outline: none; }
    &::placeholder { color: var(--bkq-search-faint); }
    &::-webkit-search-cancel-button { appearance: none; }
  }
  & kbd {
    flex: none;
    min-width: 24px; height: 24px; display: grid; place-items: center;
    font: 500 12px/1 ui-monospace, Menlo, monospace;
    color: var(--bkq-search-muted);
    border: 1px solid var(--bkq-search-line);
    border-bottom-width: 2px;
    border-radius: 6px;
    transition: opacity .2s;
  }
  &:has(input:focus-visible), &:has(input:focus) {
    border-color: var(--bkq-search-accent);
    box-shadow: 0 0 0 4px color-mix(in oklch, var(--bkq-search-accent) 16%, transparent), 0 8px 24px -14px color-mix(in oklch, var(--bkq-search-ink) 30%, transparent);
    & svg { stroke: var(--bkq-search-accent); }
    & kbd { opacity: 0; }
  }
}
.bkq-search-sr { position: absolute; width: 1px; height: 1px; overflow: hidden; clip-path: inset(50%); white-space: nowrap; }

.bkq-search-cats {
  display: flex; gap: 6px;
  overflow-x: auto; scrollbar-width: none;
  margin-inline: calc(var(--bkq-search-gutter) * -1);
  padding: 2px var(--bkq-search-gutter) 4px;
  &::-webkit-scrollbar { display: none; }
}
.bkq-search-cat {
  flex: none;
  display: inline-flex; align-items: center; gap: 7px;
  height: 34px; padding: 0 8px 0 13px;
  border: 1px solid var(--bkq-search-line);
  border-radius: 999px;
  background: transparent;
  font-size: 13.5px; font-weight: 520;
  cursor: pointer;
  transition: background-color .2s, border-color .2s, color .2s, scale .35s var(--bkq-search-spring);
  & span {
    min-width: 22px; height: 20px; padding: 0 6px;
    display: grid; place-items: center;
    border-radius: 999px;
    font-size: 11.5px; font-weight: 600;
    font-variant-numeric: tabular-nums;
    background: var(--bkq-search-line);
    color: var(--bkq-search-muted);
    transition: background-color .2s, color .2s;
  }
  &:hover { border-color: color-mix(in oklch, var(--bkq-search-ink) 25%, var(--bkq-search-bg)); }
  &:active { scale: .96; }
  &[aria-pressed="true"] {
    background: var(--bkq-search-ink); border-color: var(--bkq-search-ink); color: var(--bkq-search-bg);
    & span { background: color-mix(in oklch, var(--bkq-search-bg) 18%, transparent); color: var(--bkq-search-bg); }
  }
  &[data-zero] span { opacity: .45; }
}
.bkq-search-status { font-size: 13px; color: var(--bkq-search-muted); font-variant-numeric: tabular-nums; min-height: 1.55em; }

.bkq-search-list { grid-area: list; border-top: 1px solid var(--bkq-search-line); align-self: start; }

.bkq-search-item {
  position: relative;
  border-bottom: 1px solid var(--bkq-search-line);
  transition: opacity .38s var(--bkq-search-out), translate .5s var(--bkq-search-spring), display .38s allow-discrete;
  transition-delay: calc(min(var(--i, 0), 10) * 32ms);
  @starting-style { opacity: 0; translate: 0 10px; }
  &[data-out] { display: none; opacity: 0; transition-delay: 0s; }

  &::before {
    content: "";
    position: absolute; left: 0; top: 14px; bottom: 14px; width: 3px;
    border-radius: 3px;
    background: var(--bkq-search-accent);
    scale: 1 0; transform-origin: 50% 0;
    transition: scale .45s var(--bkq-search-out);
  }
  &[open]::before { scale: 1 1; }

  & summary {
    list-style: none;
    display: grid;
    grid-template-columns: minmax(0, 1fr) auto 28px;
    align-items: center;
    gap: 12px;
    padding: 18px 2px 18px 16px;
    cursor: pointer;
    border-radius: 10px;
    transition: background-color .2s;
    &::-webkit-details-marker { display: none; }
    &:hover { background: var(--bkq-search-tint); }
    &:focus-visible { outline-offset: -2px; }
  }
}
.bkq-search-q { font-size: clamp(15.5px, .35cqi + 14px, 17.5px); font-weight: 600; letter-spacing: -.012em; text-wrap: pretty; }
.bkq-search-hits {
  grid-column: 2;
  font-size: 11.5px; font-weight: 600; white-space: nowrap;
  font-variant-numeric: tabular-nums;
  padding: 3px 8px; border-radius: 999px;
  background: var(--bkq-search-mark);
  color: color-mix(in oklch, var(--bkq-search-ink) 85%, var(--bkq-search-mark));
  transition: opacity .2s, scale .35s var(--bkq-search-spring);
  &:empty { display: none; }
  @starting-style { opacity: 0; scale: .6; }
  .bkq-search-item[open] & { opacity: 0; scale: .8; }
}
.bkq-search-chev {
  grid-column: 3;
  width: 28px; height: 28px; padding: 6px;
  border-radius: 50%;
  border: 1px solid var(--bkq-search-line);
  fill: none; stroke: currentColor; stroke-width: 1.8; stroke-linecap: round;
  transition: rotate .45s var(--bkq-search-spring), background-color .2s, border-color .2s, color .2s;
  .bkq-search-item[open] & { rotate: 135deg; background: var(--bkq-search-ink); border-color: var(--bkq-search-ink); color: var(--bkq-search-bg); }
}
.bkq-search-a {
  padding: 0 46px 20px 16px;
  color: color-mix(in oklch, var(--bkq-search-ink) 78%, var(--bkq-search-bg));
  max-width: 64ch;
  transition: opacity .4s var(--bkq-search-out) .06s, translate .5s var(--bkq-search-out) .06s;
  & p { text-wrap: pretty; }
  .bkq-search-item:not([open]) & { opacity: 0; translate: 0 -6px; }
}
.bkq-search-tag {
  display: inline-block; margin-top: 10px;
  font: 500 11px/1 ui-monospace, Menlo, monospace; letter-spacing: .04em; text-transform: uppercase;
  color: var(--bkq-search-accent);
}

@supports (interpolate-size: allow-keywords) {
  .bkq-search-item::details-content {
    block-size: 0;
    overflow: clip;
    transition: block-size .42s var(--bkq-search-out), content-visibility .42s allow-discrete;
  }
  .bkq-search-item[open]::details-content { block-size: auto; }
}

.bkq-search-empty {
  display: grid; justify-items: start; gap: 8px;
  padding: 36px 16px;
  @starting-style { opacity: 0; translate: 0 8px; }
  transition: opacity .3s, translate .45s var(--bkq-search-spring);
  &[hidden] { display: none; }
  & svg { width: 40px; height: 40px; fill: none; stroke: var(--bkq-search-faint); stroke-width: 1.6; stroke-linecap: round; margin-bottom: 4px; }
}
.bkq-search-emptyt { font-size: 18px; font-weight: 620; letter-spacing: -.015em; overflow-wrap: anywhere; }
.bkq-search-emptyd { color: var(--bkq-search-muted); }
.bkq-search-sugg {
  display: flex; flex-wrap: wrap; gap: 6px; margin-top: 4px;
  & button {
    height: 32px; padding: 0 12px;
    border: 1px dashed color-mix(in oklch, var(--bkq-search-ink) 28%, var(--bkq-search-bg));
    border-radius: 8px; background: var(--bkq-search-card);
    font: 500 13px/1 ui-monospace, Menlo, monospace;
    cursor: pointer;
    transition: border-color .2s, background-color .2s, translate .3s var(--bkq-search-spring);
    &:hover { border-style: solid; border-color: var(--bkq-search-accent); background: var(--bkq-search-tint); translate: 0 -2px; }
  }
}

.bkq-search-help {
  grid-area: help;
  display: grid; gap: 14px; align-content: start;
  padding: 20px;
  border-radius: 16px;
  background: var(--bkq-search-tint);
  border: 1px solid color-mix(in oklch, var(--bkq-search-accent) 18%, var(--bkq-search-bg));
  & p { color: var(--bkq-search-muted); text-wrap: pretty; max-width: 40ch; }
  & b { color: var(--bkq-search-ink); font-weight: 640; }
}
.bkq-search-faces {
  display: flex;
  & span {
    width: 34px; height: 34px; margin-right: -8px;
    display: grid; place-items: center;
    border-radius: 50%;
    border: 2px solid var(--bkq-search-tint);
    font-size: 11px; font-weight: 700; letter-spacing: .02em;
    background: oklch(86% 0.07 var(--h));
    color: oklch(32% 0.08 var(--h));
  }
}
.bkq-search-btn {
  justify-self: start;
  display: inline-flex; align-items: center; gap: 8px;
  height: 40px; padding: 0 14px 0 16px;
  border-radius: 10px;
  background: var(--bkq-search-ink); color: var(--bkq-search-bg);
  font-size: 14px; font-weight: 600; text-decoration: none;
  transition: background-color .2s;
  & svg { width: 16px; height: 16px; fill: none; stroke: currentColor; stroke-width: 2; stroke-linecap: round; stroke-linejoin: round; transition: translate .35s var(--bkq-search-spring); }
  &:hover { background: color-mix(in oklch, var(--bkq-search-ink) 86%, var(--bkq-search-accent)); & svg { translate: 3px 0; } }
}

@container bkq-search (min-width: 760px) {
  .bkq-search-in {
    grid-template-columns: minmax(0, 5fr) minmax(0, 7fr);
    grid-template-rows: auto auto 1fr;
    grid-template-areas: "head list" "tools list" "help list";
    gap: 28px clamp(40px, 6cqi, 96px);
  }
  .bkq-search-cats { flex-wrap: wrap; overflow: visible; margin-inline: 0; padding-inline: 0; }
  .bkq-search-help { align-self: end; }
  .bkq-search-list { border-top: 0; }
  .bkq-search-item:first-of-type { border-top: 1px solid var(--bkq-search-line); }
}

@media (prefers-reduced-motion: reduce) {
  .bkq-search-item, .bkq-search-a, .bkq-search-hits, .bkq-search-chev, .bkq-search-item::before, .bkq-search-empty, .bkq-search-cat, .bkq-search-btn svg {
    transition-duration: .01s !important;
    transition-delay: 0s !important;
  }
  .bkq-search-item::details-content { transition: none !important; }
}

.bkq-search-more {
  width: 100%;
  display: flex; align-items: center; gap: 10px;
  padding: 16px 2px 16px 16px;
  border: 0; border-bottom: 1px solid var(--bkq-search-line);
  background: none; cursor: pointer; text-align: left;
  font-size: 14.5px; font-weight: 600; color: var(--bkq-search-accent);
  border-radius: 0;
  transition: background-color .2s;
  & small { font-size: 12.5px; font-weight: 500; color: var(--bkq-search-muted); font-variant-numeric: tabular-nums; }
  & svg { margin-left: auto; width: 28px; height: 28px; padding: 5px; fill: none; stroke: currentColor; stroke-width: 1.8; stroke-linecap: round; stroke-linejoin: round; transition: rotate .45s var(--bkq-search-spring); }
  &:hover { background: var(--bkq-search-tint); }
  &[aria-expanded="true"] svg { rotate: 180deg; }
  &[hidden] { display: none; }
}

