const doc = root.ownerDocument;
// Per-instance id suffix so aria references survive the section being pasted twice.
const uid = Math.random().toString(36).slice(2, 7);
root.querySelectorAll('[id]').forEach((n) => { n.id += '-' + uid; });
['aria-controls', 'aria-describedby', 'aria-labelledby'].forEach((a) => root.querySelectorAll('[' + a + ']').forEach((n) => {
  n.setAttribute(a, n.getAttribute(a).split(' ').map((s) => s + '-' + uid).join(' '));
}));
if (root.hasAttribute('aria-labelledby')) root.setAttribute('aria-labelledby', root.getAttribute('aria-labelledby') + '-' + uid);
const input = root.querySelector('.bkq-search-input');
const status = root.querySelector('.bkq-search-status');
const empty = root.querySelector('.bkq-search-empty');
const emptyQ = root.querySelector('.bkq-search-emptyq');
const chips = [...root.querySelectorAll('.bkq-search-cat')];
const more = root.querySelector('.bkq-search-more');
let expanded = false;
const NAMES = { all: '', rates: 'Rates & labels', intl: 'International', returns: 'Returns', account: 'Account & billing' };

const items = [...root.querySelectorAll('.bkq-search-item')].map((el) => {
  const q = el.querySelector('.bkq-search-q');
  const a = el.querySelector('.bkq-search-a p');
  return { el, q, a, sum: el.querySelector('summary'), badge: el.querySelector('.bkq-search-hits'),
           cat: el.dataset.cat, top: el.hasAttribute('data-top'), text: (q.textContent + ' ' + a.textContent).toLowerCase() };
});

// One Highlight is shared by every instance on the page (the registry is document-global);
// each instance only ever adds and deletes its own Ranges, and prunes any left on detached nodes.
const HL = 'bkq-search-hit';
const reg = typeof CSS !== 'undefined' && CSS.highlights && typeof Highlight === 'function' ? CSS.highlights : null;
let shared = null;
if (reg) {
  shared = reg.get(HL);
  if (!shared) { shared = new Highlight(); reg.set(HL, shared); }
}
let mine = [];

function clearHits() {
  if (shared) {
    mine.forEach((r) => shared.delete(r));
    shared.forEach((r) => { if (!r.startContainer.isConnected) shared.delete(r); });
  } else {
    root.querySelectorAll('mark.bkq-search-mark').forEach((m) => {
      const p = m.parentNode; m.replaceWith(...m.childNodes); p.normalize();
    });
  }
  mine = [];
}

// Merge overlapping matches per text node so "label" + "lab" never produce nested ranges.
function paint(el, terms) {
  const walker = doc.createTreeWalker(el, NodeFilter.SHOW_TEXT);
  const nodes = [];
  for (let t = walker.nextNode(); t; t = walker.nextNode()) nodes.push(t);
  let count = 0;
  nodes.forEach((t) => {
    const s = t.data.toLowerCase();
    const spans = [];
    terms.forEach((term) => {
      for (let k = s.indexOf(term); k !== -1; k = s.indexOf(term, k + term.length)) spans.push([k, k + term.length]);
    });
    if (!spans.length) return;
    spans.sort((x, y) => x[0] - y[0]);
    const merged = [spans[0].slice()];
    spans.slice(1).forEach(([a, b]) => {
      const last = merged[merged.length - 1];
      if (a <= last[1]) last[1] = Math.max(last[1], b); else merged.push([a, b]);
    });
    count += merged.length;
    if (shared) {
      merged.forEach(([a, b]) => {
        const r = new Range(); r.setStart(t, a); r.setEnd(t, b);
        shared.add(r); mine.push(r);
      });
    } else {
      for (let m = merged.length - 1; m >= 0; m--) {
        const [a, b] = merged[m];
        const hit = t.splitText(a); hit.splitText(b - a);
        const mark = doc.createElement('mark'); mark.className = 'bkq-search-mark';
        hit.replaceWith(mark); mark.append(hit);
      }
    }
  });
  return count;
}

let cat = 'all';
function run() {
  const raw = input.value.trim();
  const terms = [...new Set(raw.toLowerCase().split(/\s+/).filter(Boolean))];
  clearHits();
  const counts = { all: 0, rates: 0, intl: 0, returns: 0, account: 0 };
  let shown = 0;
  // With no query and no topic, only the eight most-asked show until "Show all" is pressed.
  const browsing = !terms.length && cat === 'all';
  items.forEach((d) => {
    const ok = terms.every((t) => d.text.includes(t));
    if (ok) { counts.all++; counts[d.cat]++; }
    const vis = ok && (cat === 'all' || d.cat === cat) && (!browsing || expanded || d.top);
    if (vis) {
      d.el.style.setProperty('--i', shown);
      d.el.removeAttribute('data-out');
      shown++;
      if (terms.length) {
        paint(d.q, terms);
        const n = paint(d.a, terms);
        d.badge.textContent = n ? n + (n === 1 ? ' match' : ' matches') + ' inside' : '';
      } else d.badge.textContent = '';
    } else {
      d.el.setAttribute('data-out', '');
      d.badge.textContent = '';
    }
  });
  chips.forEach((c) => {
    const n = counts[c.dataset.cat];
    c.querySelector('span').textContent = n;
    c.toggleAttribute('data-zero', n === 0);
  });
  const where = cat === 'all' ? '' : ' in ' + NAMES[cat];
  more.hidden = !browsing;
  more.setAttribute('aria-expanded', String(expanded));
  more.querySelector('span').textContent = expanded ? 'Show the 8 most-asked' : 'Show all 18 questions';
  more.querySelector('small').textContent = expanded ? '' : '+10 more';
  if (browsing) status.textContent = expanded ? 'Showing all 18 answers' : 'The 8 most-asked of 18 answers';
  else if (!terms.length) status.textContent = shown + ' answers' + where;
  else if (shown) status.textContent = shown + (shown === 1 ? ' answer mentions “' : ' answers mention “') + raw + '”' + where;
  else status.textContent = 'No answers mention “' + raw + '”' + where;
  empty.hidden = shown !== 0;
  emptyQ.textContent = raw || NAMES[cat];
}

input.addEventListener('input', run);

const visible = () => items.filter((d) => !d.el.hasAttribute('data-out')).map((d) => d.sum);

input.addEventListener('keydown', (e) => {
  if (e.key === 'Escape') {
    if (input.value) { input.value = ''; run(); } else input.blur();
    e.preventDefault();
  } else if (e.key === 'ArrowDown') {
    const v = visible(); if (v[0]) { e.preventDefault(); v[0].focus(); }
  } else if (e.key === 'Enter') {
    const v = visible(); if (!v[0]) return;
    e.preventDefault(); v[0].parentElement.open = true; v[0].focus();
  }
});

root.addEventListener('keydown', (e) => {
  const sum = e.target.closest && e.target.closest('.bkq-search-item > summary');
  if (!sum) return;
  const v = visible(); const k = v.indexOf(sum);
  let next = null;
  if (e.key === 'ArrowDown') next = v[k + 1];
  else if (e.key === 'ArrowUp') next = k === 0 ? input : v[k - 1];
  else if (e.key === 'Home') next = v[0];
  else if (e.key === 'End') next = v[v.length - 1];
  else if (e.key === 'Escape' && sum.parentElement.open) { sum.parentElement.open = false; e.preventDefault(); return; }
  if (next) { e.preventDefault(); next.focus(); }
});

more.addEventListener('click', () => { expanded = !expanded; run(); });

chips.forEach((c) => c.addEventListener('click', () => {
  cat = c.dataset.cat;
  chips.forEach((x) => x.setAttribute('aria-pressed', String(x === c)));
  run();
}));

root.querySelectorAll('.bkq-search-sugg button').forEach((b) => b.addEventListener('click', () => {
  input.value = b.dataset.q;
  if (cat !== 'all') { cat = 'all'; chips.forEach((x) => x.setAttribute('aria-pressed', String(x.dataset.cat === 'all'))); }
  run(); input.focus();
}));

// "/" focuses the search, but only for the instance that is actually on screen.
let onScreen = false;
const io = new IntersectionObserver(([en]) => { onScreen = en.isIntersecting; });
io.observe(root);
function onSlash(e) {
  if (!root.isConnected) { doc.removeEventListener('keydown', onSlash); io.disconnect(); return; }
  if (e.key !== '/' || !onScreen || e.defaultPrevented) return;
  const t = e.target;
  if (t.closest && t.closest('input, textarea, select, [contenteditable=""], [contenteditable="true"]')) return;
  e.preventDefault(); input.focus(); input.select();
}
doc.addEventListener('keydown', onSlash);

run();

