@property --bkq-contact-p { syntax: "<number>"; inherits: true; initial-value: 0; }
@property --bkq-contact-n { syntax: "<integer>"; inherits: true; initial-value: 0; }

.bkq-contact {
  /* re-theme with these four */
  --bkq-contact-paper: oklch(96.4% 0.009 85);
  --bkq-contact-ink: oklch(20% 0.012 60);
  --bkq-contact-red: oklch(57% 0.2 31);
  --bkq-contact-ok: oklch(52% 0.11 150);

  --bkq-contact-muted: color-mix(in oklch, var(--bkq-contact-ink) 62%, var(--bkq-contact-paper));
  --bkq-contact-faint: color-mix(in oklch, var(--bkq-contact-ink) 38%, var(--bkq-contact-paper));
  --bkq-contact-line: color-mix(in oklch, var(--bkq-contact-ink) 14%, var(--bkq-contact-paper));
  --bkq-contact-hair: color-mix(in oklch, var(--bkq-contact-ink) 6%, var(--bkq-contact-paper));
  --bkq-contact-sheet: color-mix(in oklch, white 55%, var(--bkq-contact-paper));
  --bkq-contact-out: cubic-bezier(.16, 1, .3, 1);
  --bkq-contact-draw: cubic-bezier(.65, 0, .35, 1);
  --bkq-contact-spring: linear(0, .02 .7%, .08 1.5%, .3 3.6%, .58 6.2%, .81 9%, .96 12%, 1.04 15.4%, 1.07 18.8%, 1.06 22.6%, 1.02 29.4%, 1 36%, .996 44%, 1);
  --bkq-contact-gutter: clamp(16px, 5cqi, 64px);

  container-type: inline-size;
  container-name: bkq-contact;
  box-sizing: border-box;
  width: 100%;
  background: var(--bkq-contact-paper);
  color: var(--bkq-contact-ink);
  font: 400 15px/1.5 system-ui, -apple-system, "Segoe UI", Roboto, sans-serif;
  -webkit-font-smoothing: antialiased;
  accent-color: var(--bkq-contact-red);

  & *, & *::before, & *::after { box-sizing: border-box; }
  & :where(h2, h3, p, dl, dd, figure, fieldset, legend) { margin: 0; padding: 0; }
  & :where(button, input, textarea) { font: inherit; color: inherit; }
  & fieldset { border: 0; min-width: 0; }
  & :focus-visible { outline: 2px solid var(--bkq-contact-red); outline-offset: 3px; }
}

.bkq-contact-in {
  position: relative;
  display: grid;
  gap: 36px;
  grid-template-columns: minmax(0, 1fr);
  grid-template-areas: "head" "form" "map";
  padding: clamp(36px, 6cqi, 80px) var(--bkq-contact-gutter);
  max-width: 1240px;
  margin-inline: auto;
}

/* ---- head ---- */
.bkq-contact-head { grid-area: head; display: grid; gap: 16px; }
.bkq-contact-brand {
  display: flex; flex-wrap: wrap; align-items: center; gap: 4px 12px;
  font-size: 14px;
  & svg { width: 28px; height: 28px; fill: none; stroke: var(--bkq-contact-ink); stroke-width: 1.6; }
  & b { font-weight: 700; letter-spacing: -.01em; }
  & em { font: 500 10.5px/1 ui-monospace, Menlo, monospace; letter-spacing: .14em; text-transform: uppercase; color: var(--bkq-contact-muted); }
}
.bkq-contact-title {
  font-size: clamp(30px, 4.4cqi + 10px, 60px);
  line-height: .98;
  letter-spacing: -.045em;
  font-weight: 700;
  text-wrap: balance;
  max-width: 15ch;
}
.bkq-contact-lede { max-width: 44ch; color: var(--bkq-contact-muted); text-wrap: pretty; font-size: clamp(15px, .4cqi + 13.5px, 17px); }

/* ---- form ---- */
.bkq-contact-formwrap { grid-area: form; position: relative; }
.bkq-contact-form {
  display: grid;
  grid-template-columns: minmax(0, 1fr);
  gap: 22px 28px;
  &[hidden] { display: none; }
}
.bkq-contact-field { display: grid; gap: 6px; align-content: start; }
.bkq-contact-field > label, .bkq-contact-field > legend {
  display: flex; gap: 10px; align-items: baseline;
  font: 600 11px/1.3 ui-monospace, Menlo, monospace;
  letter-spacing: .1em; text-transform: uppercase;
  color: var(--bkq-contact-muted);
  & span { color: var(--bkq-contact-faint); transition: color .2s; }
}
.bkq-contact-field > legend { margin-bottom: 8px; float: left; width: 100%; }
.bkq-contact-field > legend + * { clear: both; }

.bkq-contact-ctl {
  position: relative;
  & input, & textarea {
    width: 100%;
    border: 0; border-bottom: 1.5px solid var(--bkq-contact-ink);
    border-radius: 0;
    background: transparent;
    padding: 8px 30px 10px 0;
    font-size: 17px; letter-spacing: -.01em;
    outline: none;
    &:focus-visible { outline: none; }
    &::placeholder { color: var(--bkq-contact-faint); }
  }
  & textarea { resize: vertical; min-height: 92px; line-height: 1.5; padding-top: 10px; }
  &::after {
    content: "";
    position: absolute; left: 0; right: 0; bottom: 0; height: 3px;
    background: var(--bkq-contact-ink);
    scale: 0 1; transform-origin: 0 50%;
    transition: scale .5s var(--bkq-contact-out), background-color .2s;
    pointer-events: none;
  }
  &:focus-within::after { scale: 1 1; }
}
.bkq-contact-ok {
  position: absolute; right: 2px; top: 10px;
  width: 20px; height: 20px;
  fill: none; stroke: var(--bkq-contact-ok); stroke-width: 2.4; stroke-linecap: round; stroke-linejoin: round;
  & path { stroke-dasharray: 1; stroke-dashoffset: 1; transition: stroke-dashoffset .45s var(--bkq-contact-out); }
}
.bkq-contact-msg {
  min-height: 18px;
  font-size: 13px; line-height: 18px;
  color: var(--bkq-contact-red);
  opacity: 0; translate: 0 -4px;
  transition: opacity .25s, translate .45s var(--bkq-contact-spring);
  text-wrap: pretty;
  & button {
    padding: 0; border: 0; background: none; cursor: pointer;
    font-weight: 650; color: var(--bkq-contact-ink);
    text-decoration: underline; text-decoration-color: var(--bkq-contact-red); text-underline-offset: 3px; text-decoration-thickness: 1.5px;
  }
}
.bkq-contact-field[data-state="hint"] .bkq-contact-msg { color: var(--bkq-contact-muted); }

/* error and success styling: :user-invalid where supported, data-state as the touched fallback */
.bkq-contact-field[data-state="error"] {
  & .bkq-contact-ctl input, & .bkq-contact-ctl textarea { border-bottom-color: var(--bkq-contact-red); }
  & .bkq-contact-ctl::after { background: var(--bkq-contact-red); }
  & > label span, & > legend span { color: var(--bkq-contact-red); }
}
.bkq-contact-ctl:has(:user-invalid) input, .bkq-contact-ctl:has(:user-invalid) textarea { border-bottom-color: var(--bkq-contact-red); }
.bkq-contact-field:is([data-state="error"], [data-state="hint"]) .bkq-contact-msg { opacity: 1; translate: 0 0; }
.bkq-contact-field[data-state="ok"] {
  & .bkq-contact-ok path { stroke-dashoffset: 0; }
  & > label span, & > legend span { color: var(--bkq-contact-ok); }
}
.bkq-contact-field[data-nudge] { animation: bkq-contact-nudge .42s var(--bkq-contact-out); }
@keyframes bkq-contact-nudge {
  20% { translate: -6px 0; } 45% { translate: 5px 0; } 70% { translate: -2px 0; } 100% { translate: 0 0; }
}

.bkq-contact-seg {
  display: grid; grid-template-columns: repeat(2, minmax(0, 1fr));
  border: 1.5px solid var(--bkq-contact-ink);
  & label { position: relative; display: grid; cursor: pointer; }
  & label:nth-child(odd) { border-right: 1.5px solid var(--bkq-contact-ink); }
  & label:nth-child(-n+2) { border-bottom: 1.5px solid var(--bkq-contact-ink); }
  & input { position: absolute; inset: 0; opacity: 0; margin: 0; cursor: pointer; }
  & span {
    display: grid; place-items: center;
    min-height: 44px; padding: 8px 10px;
    font-size: 14px; font-weight: 560; text-align: center;
    background-image: linear-gradient(var(--bkq-contact-ink), var(--bkq-contact-ink));
    background-repeat: no-repeat;
    background-size: 100% 0%;
    background-position: 0 100%;
    transition: background-size .45s var(--bkq-contact-out), color .3s;
  }
  & label:hover span { background-color: var(--bkq-contact-hair); }
  & label:has(:checked) span { background-size: 100% 100%; color: var(--bkq-contact-paper); }
  & label:has(:focus-visible) { outline: 2px solid var(--bkq-contact-red); outline-offset: 2px; z-index: 1; }
}
.bkq-contact-field[data-state="error"] .bkq-contact-seg { border-color: var(--bkq-contact-red); }

.bkq-contact-under { display: flex; justify-content: space-between; gap: 12px; }
.bkq-contact-count { font: 500 11.5px/18px ui-monospace, Menlo, monospace; color: var(--bkq-contact-faint); font-variant-numeric: tabular-nums; white-space: nowrap; }

.bkq-contact-foot {
  display: flex; flex-wrap: wrap; align-items: center; justify-content: space-between; gap: 16px;
  padding-top: 6px;
}
.bkq-contact-meter {
  display: flex; align-items: center; gap: 4px;
  transition: --bkq-contact-p .7s var(--bkq-contact-out), --bkq-contact-n .7s var(--bkq-contact-out);
  & i {
    width: 22px; height: 6px;
    background: var(--bkq-contact-line);
    position: relative; overflow: hidden;
    &::after {
      content: ""; position: absolute; inset: 0;
      background: var(--bkq-contact-ink);
      transform-origin: 0 50%;
      scale: clamp(0, var(--bkq-contact-p) - var(--k), 1) 1;
    }
  }
  & i:nth-child(1) { --k: 0; } & i:nth-child(2) { --k: 1; } & i:nth-child(3) { --k: 2; } & i:nth-child(4) { --k: 3; }
}
.bkq-contact-done {
  margin-left: 8px;
  font: 600 11px/1 ui-monospace, Menlo, monospace; letter-spacing: .08em; text-transform: uppercase;
  color: var(--bkq-contact-muted);
  font-variant-numeric: tabular-nums;
  counter-reset: bkq-contact-n var(--bkq-contact-n);
  &::before { content: counter(bkq-contact-n) " of 4 ready"; }
}
.bkq-contact-send {
  display: inline-flex; align-items: center; gap: 14px;
  height: 52px; padding: 0 20px 0 22px;
  border: 0; border-radius: 0;
  background: var(--bkq-contact-ink); color: var(--bkq-contact-paper);
  font-size: 15px; font-weight: 640; letter-spacing: -.005em;
  cursor: pointer;
  position: relative; overflow: hidden; isolation: isolate;
  & svg { width: 18px; height: 18px; fill: none; stroke: currentColor; stroke-width: 2; stroke-linecap: square; transition: translate .45s var(--bkq-contact-spring); }
  &::before {
    content: ""; position: absolute; inset: 0; z-index: -1;
    background: var(--bkq-contact-red);
    clip-path: inset(0 100% 0 0);
    transition: clip-path .5s var(--bkq-contact-out);
  }
  &:hover svg { translate: 4px 0; }
  &:active { translate: 0 1px; }
}
.bkq-contact-form:not(:has(:invalid)) .bkq-contact-send::before { clip-path: inset(0 0 0 0); }
.bkq-contact-sr { position: absolute; width: 1px; height: 1px; overflow: hidden; clip-path: inset(50%); white-space: nowrap; }

/* ---- sent ---- */
.bkq-contact-done-panel {
  display: grid; gap: 14px; align-content: start; justify-items: start;
  padding: 28px 0;
  outline: none;
  &[hidden] { display: none; }
  & > * { transition: opacity .5s var(--bkq-contact-out), translate .7s var(--bkq-contact-out); transition-delay: calc(var(--i, 0) * 80ms + 300ms); @starting-style { opacity: 0; translate: 0 12px; } }
  & > :nth-child(2) { --i: 1; } & > :nth-child(3) { --i: 2; } & > :nth-child(4) { --i: 3; } & > :nth-child(5) { --i: 4; }
  & svg { width: 64px; height: 64px; fill: none; stroke: var(--bkq-contact-red); stroke-width: 2.4; stroke-linejoin: round; }
  & svg :is(rect, path) { stroke-dasharray: 1; stroke-dashoffset: 0; transition: stroke-dashoffset 1s var(--bkq-contact-draw) .1s; @starting-style { stroke-dashoffset: 1; } }
  & svg path { transition-delay: .6s; }
  & h3 { font-size: clamp(28px, 3cqi + 12px, 44px); line-height: 1; letter-spacing: -.04em; font-weight: 700; }
  & .bkq-contact-when { max-width: 44ch; color: var(--bkq-contact-muted); text-wrap: pretty; & b { color: var(--bkq-contact-ink); } }
}
.bkq-contact-ref { font: 600 11px/1 ui-monospace, Menlo, monospace; letter-spacing: .12em; text-transform: uppercase; color: var(--bkq-contact-muted); & b { color: var(--bkq-contact-red); } }
.bkq-contact-again {
  margin-top: 6px; padding: 0 0 2px; border: 0; background: none; cursor: pointer;
  font-weight: 640; border-bottom: 1.5px solid currentColor;
  &:hover { color: var(--bkq-contact-red); }
}

/* ---- map ---- */
.bkq-contact-map { grid-area: map; display: grid; gap: 0; align-content: start; }
.bkq-contact-map figure { border: 1.5px solid var(--bkq-contact-ink); background: var(--bkq-contact-sheet); }
.bkq-contact-plan {
  display: block; width: 100%; height: auto;
  & .bkq-contact-water { fill: color-mix(in oklch, var(--bkq-contact-ink) 7%, var(--bkq-contact-paper)); }
  & .bkq-contact-waves { fill: none; stroke: var(--bkq-contact-faint); stroke-width: 1; opacity: .6; }
  & .bkq-contact-quay { fill: none; stroke: var(--bkq-contact-ink); stroke-width: 2; }
  & .bkq-contact-park { fill: color-mix(in oklch, var(--bkq-contact-ok) 13%, var(--bkq-contact-paper)); }
  & .bkq-contact-trees circle { fill: none; stroke: color-mix(in oklch, var(--bkq-contact-ok) 70%, var(--bkq-contact-paper)); stroke-width: 1.2; }
  & .bkq-contact-blocks rect { fill: color-mix(in oklch, var(--bkq-contact-ink) 8%, var(--bkq-contact-paper)); }
  & .bkq-contact-street { fill: none; stroke: var(--bkq-contact-ink); stroke-width: 1.3; }
  & .bkq-contact-main { stroke-width: 3; }
  & .bkq-contact-rail { fill: none; stroke: var(--bkq-contact-ink); stroke-width: 1.4; }
  & .bkq-contact-ties { fill: none; stroke: var(--bkq-contact-ink); stroke-width: 6; stroke-dasharray: 1.2 7; opacity: .55; }
  & .bkq-contact-labels text { font: 600 8.5px ui-monospace, Menlo, monospace; letter-spacing: .12em; fill: var(--bkq-contact-muted); }
  & .bkq-contact-cl { font-size: 7.5px; fill: var(--bkq-contact-faint); }
  & .bkq-contact-customs { fill: color-mix(in oklch, var(--bkq-contact-ink) 13%, var(--bkq-contact-paper)); }
  & .bkq-contact-pier { fill: none; stroke: color-mix(in oklch, var(--bkq-contact-ink) 45%, var(--bkq-contact-paper)); stroke-width: 7; }
  & .bkq-contact-ferry { fill: none; stroke: var(--bkq-contact-faint); stroke-width: 1.2; stroke-dasharray: 4 4; }
  & .bkq-contact-wl { fill: var(--bkq-contact-faint); }
  & .bkq-contact-station { & circle { fill: var(--bkq-contact-paper); stroke: var(--bkq-contact-ink); stroke-width: 2; } & text { font: 700 10px system-ui, sans-serif; text-anchor: middle; fill: var(--bkq-contact-ink); } }
  & .bkq-contact-stl { font: 600 9px system-ui, sans-serif; fill: var(--bkq-contact-ink); }
  & .bkq-contact-route {
    fill: none; stroke: var(--bkq-contact-red); stroke-width: 3.5; stroke-linecap: round; stroke-linejoin: round;
    stroke-dasharray: 1; stroke-dashoffset: 1;
    transition: stroke-dashoffset 1.6s var(--bkq-contact-draw);
  }
  & .bkq-contact-pin {
    & rect { fill: var(--bkq-contact-red); stroke: var(--bkq-contact-paper); stroke-width: 2; }
    & .bkq-contact-pulse { fill: var(--bkq-contact-red); opacity: .25; transform-box: fill-box; transform-origin: center; animation: bkq-contact-pulse 2.4s var(--bkq-contact-out) infinite; }
  }
  & .bkq-contact-walker { fill: var(--bkq-contact-paper); stroke: var(--bkq-contact-red); stroke-width: 2.5; opacity: 0; transition: opacity .3s; }
  & .bkq-contact-north { & path { fill: var(--bkq-contact-ink); } & text { font: 700 8px ui-monospace, Menlo, monospace; text-anchor: middle; fill: var(--bkq-contact-ink); } }
  & .bkq-contact-scale { & path { fill: none; stroke: var(--bkq-contact-ink); stroke-width: 1.2; } & text { font: 600 7.5px ui-monospace, Menlo, monospace; fill: var(--bkq-contact-ink); } }
  & .bkq-contact-d { stroke-dasharray: 1; stroke-dashoffset: 1; transition: stroke-dashoffset 1.3s var(--bkq-contact-draw); transition-delay: calc(var(--i) * 90ms); }
  & .bkq-contact-ties, & .bkq-contact-labels, & .bkq-contact-blocks, & .bkq-contact-park, & .bkq-contact-trees, & .bkq-contact-water, & .bkq-contact-waves, & .bkq-contact-pier, & .bkq-contact-ferry { opacity: 0; transition: opacity .9s ease-out .6s; }
}
@keyframes bkq-contact-pulse { 0% { scale: .6; opacity: .4; } 100% { scale: 2.2; opacity: 0; } }
.bkq-contact[data-drawn] .bkq-contact-plan {
  & .bkq-contact-d { stroke-dashoffset: 0; }
  & .bkq-contact-ties, & .bkq-contact-labels, & .bkq-contact-blocks, & .bkq-contact-park, & .bkq-contact-trees, & .bkq-contact-water, & .bkq-contact-pier, & .bkq-contact-ferry { opacity: 1; }
  & .bkq-contact-waves { opacity: .6; }
}
.bkq-contact[data-walk] .bkq-contact-plan {
  & .bkq-contact-route { stroke-dashoffset: 0; }
  & .bkq-contact-walker { opacity: 1; }
}

.bkq-contact-map figcaption { border-top: 1.5px solid var(--bkq-contact-ink); }
.bkq-contact-walk {
  width: 100%;
  display: flex; align-items: center; gap: 10px;
  min-height: 48px; padding: 8px 14px;
  border: 0; background: none; cursor: pointer; text-align: left;
  font-size: 14px; font-weight: 600;
  transition: background-color .2s, color .2s;
  & svg { width: 20px; height: 20px; flex: none; fill: none; stroke: currentColor; stroke-width: 1.7; stroke-linecap: round; stroke-linejoin: round; }
  & b { margin-left: auto; font: 600 11.5px/1 ui-monospace, Menlo, monospace; letter-spacing: .04em; color: var(--bkq-contact-muted); font-variant-numeric: tabular-nums; white-space: nowrap; }
  &:hover { background: var(--bkq-contact-hair); }
  &[aria-pressed="true"] { background: var(--bkq-contact-ink); color: var(--bkq-contact-paper); & b { color: color-mix(in oklch, var(--bkq-contact-paper) 70%, var(--bkq-contact-ink)); } }
  &:focus-visible { outline-offset: -4px; }
}
.bkq-contact-facts {
  display: grid; grid-template-columns: minmax(0, 1fr);
  border: 1.5px solid var(--bkq-contact-ink); border-top: 0;
  & div { padding: 12px 14px; display: grid; grid-template-columns: 64px minmax(0, 1fr); gap: 2px 12px; align-items: baseline; min-width: 0; }
  & div + div { border-top: 1px solid var(--bkq-contact-line); }
  & dt { font: 600 10.5px/1.2 ui-monospace, Menlo, monospace; letter-spacing: .12em; text-transform: uppercase; color: var(--bkq-contact-red); }
  & dd { font-size: 13.5px; line-height: 1.45; overflow-wrap: anywhere; }
  & a { color: inherit; text-decoration: underline; text-decoration-color: var(--bkq-contact-line); text-underline-offset: 3px; transition: text-decoration-color .2s; &:hover { text-decoration-color: var(--bkq-contact-red); } }
}

@container bkq-contact (min-width: 560px) {
  .bkq-contact-form { grid-template-columns: repeat(2, minmax(0, 1fr)); }
  .bkq-contact-wide { grid-column: 1 / -1; }
  .bkq-contact-seg { grid-template-columns: repeat(4, minmax(0, 1fr)); }
  .bkq-contact-seg label:nth-child(odd) { border-right: 0; }
  .bkq-contact-seg label:not(:last-child) { border-right: 1.5px solid var(--bkq-contact-ink); }
  .bkq-contact-seg label:nth-child(-n+2) { border-bottom: 0; }
  .bkq-contact-facts { grid-template-columns: repeat(2, minmax(0, 1fr)); }
  .bkq-contact-facts div:nth-child(odd) { border-right: 1px solid var(--bkq-contact-line); }
  .bkq-contact-facts div:nth-child(2) { border-top: 0; }
  .bkq-contact-facts div:nth-child(3) { border-top: 1px solid var(--bkq-contact-line); }
}
@container bkq-contact (min-width: 600px) and (max-width: 899.98px) {
  .bkq-contact-map { grid-template-columns: minmax(0, 1.25fr) minmax(0, 1fr); align-items: start; }
  .bkq-contact-facts { border-top: 1.5px solid var(--bkq-contact-ink); border-left: 0; grid-template-columns: minmax(0, 1fr); }
  .bkq-contact-facts div { grid-template-columns: minmax(0, 1fr); border-right: 0 !important; }
  .bkq-contact-facts div:nth-child(2) { border-top: 1px solid var(--bkq-contact-line); }
}
@container bkq-contact (min-width: 900px) {
  .bkq-contact-in {
    grid-template-columns: minmax(0, 7fr) minmax(0, 5fr);
    grid-template-areas: "head map" "form map";
    grid-template-rows: auto 1fr;
    gap: 40px clamp(40px, 5cqi, 80px);
    &::before {
      content: ""; position: absolute; inset: 0 var(--bkq-contact-gutter); pointer-events: none;
      background: repeating-linear-gradient(90deg, var(--bkq-contact-hair) 0 1px, transparent 1px calc(100% / 12));
      border-right: 1px solid var(--bkq-contact-hair);
    }
  }
  .bkq-contact-head, .bkq-contact-formwrap, .bkq-contact-map { position: relative; }
  .bkq-contact-map { align-self: start; margin-top: 6px; }
  .bkq-contact-facts { grid-template-columns: minmax(0, 1fr); }
  .bkq-contact-facts div:nth-child(odd) { border-right: 0; }
  .bkq-contact-facts div:nth-child(2) { border-top: 1px solid var(--bkq-contact-line); }
}

@media (prefers-reduced-motion: reduce) {
  .bkq-contact-plan .bkq-contact-d, .bkq-contact-plan .bkq-contact-route { transition: none; }
  .bkq-contact-plan :is(.bkq-contact-ties, .bkq-contact-labels, .bkq-contact-blocks, .bkq-contact-park, .bkq-contact-trees, .bkq-contact-water, .bkq-contact-waves, .bkq-contact-pier, .bkq-contact-ferry) { transition: none; }
  .bkq-contact-plan .bkq-contact-pulse { animation: none; opacity: .18; scale: 1.6; }
  .bkq-contact-field[data-nudge] { animation: none; }
  .bkq-contact-done-panel > *, .bkq-contact-done-panel svg :is(rect, path) { transition: none; }
  .bkq-contact-meter { transition: none; }
  .bkq-contact-send::before, .bkq-contact-ctl::after, .bkq-contact-seg span { transition-duration: .01s; }
}

