// Give every id a per-instance suffix so labels and aria references survive the section being pasted twice.
const uid = Math.random().toString(36).slice(2, 7);
root.querySelectorAll('[id]').forEach((el) => { el.id += '-' + uid; });
['for', 'aria-describedby', 'aria-labelledby'].forEach((a) => root.querySelectorAll('[' + a + ']').forEach((el) => {
  el.setAttribute(a, el.getAttribute(a).split(' ').map((s) => s + '-' + uid).join(' '));
}));
if (root.hasAttribute('aria-labelledby')) root.setAttribute('aria-labelledby', root.getAttribute('aria-labelledby') + '-' + uid);

const reduce = matchMedia('(prefers-reduced-motion: reduce)');
const form = root.querySelector('.bkq-contact-form');
const panel = root.querySelector('.bkq-contact-done-panel');
const live = root.querySelector('.bkq-contact-sr');
const count = root.querySelector('.bkq-contact-count');
const field = (f) => root.querySelector('.bkq-contact-field[data-f="' + f + '"]');
const radios = [...form.querySelectorAll('input[name="type"]')];
// form.name is the form's own name attribute, so controls are looked up explicitly.
const inp = { name: form.querySelector('[name="name"]'), email: form.querySelector('[name="email"]'), message: form.querySelector('[name="message"]') };

const TYPO = { con: 'com', cmo: 'com', cpm: 'com', ocm: 'com', vom: 'com', comm: 'com', coom: 'com', nte: 'net', ogr: 'org', 'co.k': 'co.uk', 'couk': 'co.uk' };
const rules = {
  name: () => {
    const v = inp.name.value.trim();
    return v.length >= 2 ? '' : v ? 'That looks a little short. How should we address you?' : 'Tell us what to call you.';
  },
  email: () => {
    const v = inp.email.value.trim();
    if (!v) return 'We need an address to reply to.';
    if (!/^[^\s@]+@[^\s@]+$/.test(v)) return 'An email needs an @, as in name@practice.co.uk.';
    if (!/^[^\s@]+@[^\s@]+\.[a-z]{2,}$/i.test(v)) return 'Add the ending after the dot, such as .com or .co.uk.';
    return '';
  },
  type: () => radios.some((r) => r.checked) ? '' : 'Pick the closest one. “Not sure yet” is a fine answer.',
  message: () => {
    const n = inp.message.value.trim().length;
    return n >= 30 ? '' : n ? 'A sentence or two more helps us prepare: 30 characters minimum, ' + n + ' so far.' : 'A few lines about the project, please.';
  },
};
const touched = new Set();

function typoFix() {
  const v = inp.email.value.trim();
  const m = v.match(/^([^\s@]+@[^\s@]+?)\.([a-z.]+)$/i);
  if (!m) return null;
  const tld = m[2].toLowerCase();
  return TYPO[tld] ? m[1] + '.' + TYPO[tld] : null;
}

function check(f, show) {
  const el = field(f);
  const msg = el.querySelector('.bkq-contact-msg');
  const err = rules[f]();
  const ctl = f === 'type' ? radios[0] : inp[f];
  ctl.setCustomValidity(f === 'type' ? '' : err);
  const fix = f === 'email' && !err ? typoFix() : null;
  if (err && show) {
    el.dataset.state = 'error'; msg.textContent = err;
  } else if (fix) {
    el.dataset.state = 'hint'; msg.textContent = 'Did you mean ';
    const b = root.ownerDocument.createElement('button');
    b.type = 'button'; b.textContent = fix; b.dataset.fix = fix;
    msg.append(b, '?');
  } else if (!err) {
    el.dataset.state = 'ok'; msg.textContent = '';
  } else {
    delete el.dataset.state; msg.textContent = '';
  }
  const target = f === 'type' ? radios : [ctl];
  target.forEach((c) => c.setAttribute('aria-invalid', String(!!err && show)));
  return !err;
}

function meter() {
  const n = Object.keys(rules).filter((f) => !rules[f]()).length;
  root.style.setProperty('--bkq-contact-p', n);
  root.style.setProperty('--bkq-contact-n', n);
}

['name', 'email', 'message'].forEach((f) => {
  inp[f].addEventListener('input', () => { check(f, touched.has(f)); meter(); });
  inp[f].addEventListener('blur', () => { if (inp[f].value.trim()) touched.add(f); check(f, touched.has(f)); });
});
inp.message.addEventListener('input', () => { count.textContent = inp.message.value.length + ' / 800'; });
radios.forEach((r) => r.addEventListener('change', () => { touched.add('type'); check('type', true); meter(); }));

root.addEventListener('click', (e) => {
  const b = e.target.closest('[data-fix]');
  if (!b) return;
  inp.email.value = b.dataset.fix;
  touched.add('email'); check('email', true); meter();
  inp.email.focus();
});

root.addEventListener('animationend', (e) => { if (e.target.dataset) delete e.target.dataset.nudge; });

function workingDaysFrom(d, n) {
  const t = new Date(d);
  while (n > 0) { t.setDate(t.getDate() + 1); const w = t.getDay(); if (w !== 0 && w !== 6) n--; }
  return t;
}

form.addEventListener('submit', (e) => {
  e.preventDefault();
  const bad = Object.keys(rules).filter((f) => { touched.add(f); return !check(f, true); });
  meter();
  if (bad.length) {
    bad.forEach((f) => { const el = field(f); delete el.dataset.nudge; void el.offsetWidth; el.dataset.nudge = ''; });
    live.textContent = bad.length === 1 ? 'One field needs attention.' : bad.length + ' fields need attention.';
    const first = bad[0] === 'type' ? radios[0] : inp[bad[0]];
    first.focus();
    return;
  }
  const text = inp.name.value + inp.email.value + inp.message.value;
  let h = 7; for (let i = 0; i < text.length; i++) h = (h * 31 + text.charCodeAt(i)) % 9000;
  root.querySelector('.bkq-contact-refno').textContent = 'HB-' + (1000 + h);
  root.querySelector('.bkq-contact-who').textContent = inp.name.value.trim().split(/\s+/)[0];
  root.querySelector('.bkq-contact-date').textContent = new Intl.DateTimeFormat('en-GB', { weekday: 'long', day: 'numeric', month: 'long' }).format(workingDaysFrom(new Date(), 2));
  form.hidden = true;
  panel.hidden = false;
  panel.focus({ preventScroll: true });
});

root.querySelector('.bkq-contact-again').addEventListener('click', () => {
  form.reset();
  touched.clear();
  Object.keys(rules).forEach((f) => { const el = field(f); delete el.dataset.state; el.querySelector('.bkq-contact-msg').textContent = ''; });
  [inp.name, inp.email, inp.message, ...radios].forEach((c) => { c.setCustomValidity(''); c.removeAttribute('aria-invalid'); });
  count.textContent = '0 / 800';
  meter();
  panel.hidden = true;
  form.hidden = false;
  inp.name.focus();
});

// ---- the map draws itself the first time it is seen ----
const plan = root.querySelector('.bkq-contact-plan');
if (reduce.matches || !('IntersectionObserver' in window)) root.dataset.drawn = '';
else {
  const io = new IntersectionObserver((en) => {
    if (en.some((x) => x.isIntersecting)) { root.dataset.drawn = ''; io.disconnect(); }
  }, { threshold: 0.25 });
  io.observe(plan);
}

// ---- walking route: the CSS draws the line, a rAF moves the walker along the same curve ----
const walk = root.querySelector('.bkq-contact-walk');
const route = root.querySelector('.bkq-contact-route');
const walker = root.querySelector('.bkq-contact-walker');
const total = route.getTotalLength();
const ease = (t) => (t < .5 ? 4 * t * t * t : 1 - Math.pow(-2 * t + 2, 3) / 2);
let raf = 0;
function place(t) {
  const p = route.getPointAtLength(total * t);
  walker.setAttribute('cx', p.x.toFixed(1));
  walker.setAttribute('cy', p.y.toFixed(1));
}
walk.addEventListener('click', () => {
  const on = walk.getAttribute('aria-pressed') !== 'true';
  walk.setAttribute('aria-pressed', String(on));
  cancelAnimationFrame(raf);
  if (!on) { delete root.dataset.walk; return; }
  root.dataset.drawn = '';
  root.dataset.walk = '';
  if (reduce.matches) { place(1); return; }
  const t0 = performance.now();
  const step = (now) => {
    if (!root.isConnected) return;
    const t = Math.min(1, (now - t0) / 1600);
    place(ease(t));
    if (t < 1) raf = requestAnimationFrame(step);
  };
  place(0);
  raf = requestAnimationFrame(step);
});

meter();

