@property --bkq-support-a { syntax: "<angle>"; inherits: true; initial-value: 0deg; }
@property --bkq-support-z { syntax: "<angle>"; inherits: true; initial-value: 0deg; }

.bkq-support {
  /* re-theme with these four */
  --bkq-support-bg: oklch(18.5% 0.008 70);
  --bkq-support-ink: oklch(94% 0.012 80);
  --bkq-support-accent: oklch(80% 0.14 78);
  --bkq-support-ok: oklch(78% 0.15 152);

  --bkq-support-lis: var(--bkq-support-accent);
  --bkq-support-tor: oklch(70% 0.15 32);
  --bkq-support-sgp: oklch(76% 0.11 175);
  --bkq-support-call: color-mix(in oklch, var(--bkq-support-ink) 55%, var(--bkq-support-bg));
  --bkq-support-muted: color-mix(in oklch, var(--bkq-support-ink) 62%, var(--bkq-support-bg));
  --bkq-support-faint: color-mix(in oklch, var(--bkq-support-ink) 34%, var(--bkq-support-bg));
  --bkq-support-line: color-mix(in oklch, var(--bkq-support-ink) 12%, var(--bkq-support-bg));
  --bkq-support-panel: color-mix(in oklch, var(--bkq-support-ink) 4.5%, var(--bkq-support-bg));
  --bkq-support-spring: linear(0, .009, .035 2.1%, .141 4.4%, .723 12.9%, .938 16.7%, 1.017 19.4%, 1.067 22.4%, 1.084 25.1%, 1.077 28.8%, 1.038 34.4%, 1.006 40.6%, .99 47.7%, .995 63.1%, 1);
  --bkq-support-out: cubic-bezier(.2, .9, .25, 1);
  --bkq-support-gutter: clamp(16px, 5cqi, 64px);

  container-type: inline-size;
  container-name: bkq-support;
  box-sizing: border-box;
  width: 100%;
  background:
    radial-gradient(60cqi 50cqi at 12% 0%, color-mix(in oklch, var(--bkq-support-accent) 9%, transparent), transparent 70%),
    var(--bkq-support-bg);
  color: var(--bkq-support-ink);
  font: 400 15px/1.5 system-ui, -apple-system, "Segoe UI", Roboto, sans-serif;
  -webkit-font-smoothing: antialiased;
  accent-color: var(--bkq-support-accent);

  & *, & *::before, & *::after { box-sizing: border-box; }
  & :where(h2, h3, p, ul, fieldset, legend) { margin: 0; padding: 0; }
  & fieldset { border: 0; min-width: 0; }
  & :focus-visible { outline: 2px solid var(--bkq-support-accent); outline-offset: 3px; border-radius: 6px; }
}

.bkq-support-in {
  display: grid;
  gap: 32px;
  grid-template-columns: minmax(0, 1fr);
  grid-template-areas: "head" "dial" "cards";
  padding: clamp(36px, 6cqi, 80px) var(--bkq-support-gutter);
  max-width: 1280px;
  margin-inline: auto;
}

.bkq-support-head { grid-area: head; display: grid; gap: 14px; }
.bkq-support-brand {
  display: flex; align-items: center; gap: 9px;
  font: 500 12px/1 ui-monospace, Menlo, monospace; letter-spacing: .08em; text-transform: uppercase;
  color: var(--bkq-support-muted);
  & svg { width: 22px; height: 22px; fill: none; stroke: var(--bkq-support-accent); stroke-width: 1.8; stroke-linecap: round; stroke-linejoin: round; }
  & b { font: 650 15px/1 system-ui, sans-serif; letter-spacing: -.01em; text-transform: none; color: var(--bkq-support-ink); }
  & span { padding-left: 9px; border-left: 1px solid var(--bkq-support-line); }
}
.bkq-support-title {
  font-size: clamp(26px, 2.8cqi + 14px, 44px);
  line-height: 1.06; letter-spacing: -.03em; font-weight: 640;
  text-wrap: balance; max-width: 22ch;
}
.bkq-support-lede { color: var(--bkq-support-muted); max-width: 58ch; text-wrap: pretty; }

/* ---- dial ---- */
.bkq-support-dialwrap { grid-area: dial; display: grid; gap: 18px; justify-items: center; align-content: start; }
.bkq-support-dial { position: relative; width: min(100%, 360px); aspect-ratio: 1; }
.bkq-support-svg {
  display: block; width: 100%; height: 100%; overflow: visible;
  & .bkq-support-night { fill: color-mix(in oklch, var(--bkq-support-ink) 3.5%, transparent); }
  & .bkq-support-ticks line { stroke: var(--bkq-support-faint); stroke-width: 1; }
  & .bkq-support-ticks line.bkq-support-hr { stroke: var(--bkq-support-muted); stroke-width: 1.4; }
  & .bkq-support-ticks text { font: 600 9.5px ui-monospace, Menlo, monospace; fill: var(--bkq-support-muted); text-anchor: middle; dominant-baseline: central; font-variant-numeric: tabular-nums; }
  & .bkq-support-tracks circle { fill: none; stroke: var(--bkq-support-line); stroke-width: 9; opacity: .7; }
  & .bkq-support-arcs {
    transform-box: view-box; transform-origin: 50% 50%;
    rotate: var(--bkq-support-z);
    transition: --bkq-support-z 1.1s var(--bkq-support-spring);
  }
  & .bkq-support-arc {
    fill: none; stroke-width: 9; stroke-linecap: round;
    stroke-dasharray: 1; stroke-dashoffset: 0;
    transition: stroke-dashoffset 1.1s var(--bkq-support-out) calc(var(--i, 0) * 120ms + 150ms), opacity .3s, stroke-width .35s var(--bkq-support-spring);
    @starting-style { stroke-dashoffset: 1; }
    &[data-desk="lis"] { stroke: var(--bkq-support-lis); }
    &[data-desk="tor"] { stroke: var(--bkq-support-tor); }
    &[data-desk="sgp"] { stroke: var(--bkq-support-sgp); }
    &[data-desk="oncall"] { stroke: var(--bkq-support-call); stroke-width: 3; stroke-dasharray: none; stroke-linecap: butt; }
  }
  & .bkq-support-hand {
    transform-box: view-box; transform-origin: 50% 50%;
    rotate: var(--bkq-support-a);
    transition: --bkq-support-a 1.3s var(--bkq-support-spring);
    & line { stroke: var(--bkq-support-ink); stroke-width: 2; stroke-linecap: round; }
    & circle { fill: var(--bkq-support-ink); stroke: var(--bkq-support-bg); stroke-width: 3; }
  }
}
.bkq-support-center {
  position: absolute; inset: 30%;
  display: grid; place-content: center; justify-items: center; gap: 3px;
  text-align: center;
}
.bkq-support-clock { font: 600 clamp(26px, 3cqi + 14px, 36px)/1 ui-monospace, Menlo, monospace; letter-spacing: -.04em; font-variant-numeric: tabular-nums; }
.bkq-support-zone { font-size: 12px; color: var(--bkq-support-muted); max-width: 16ch; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
.bkq-support-staffed {
  margin-top: 6px;
  display: inline-flex; align-items: center; gap: 6px;
  font-size: 11.5px; color: var(--bkq-support-muted); white-space: nowrap;
  & b { color: var(--bkq-support-ink); font-variant-numeric: tabular-nums; }
  & i { width: 7px; height: 7px; border-radius: 50%; background: var(--bkq-support-faint); }
}
.bkq-support[data-live] .bkq-support-staffed i { background: var(--bkq-support-ok); box-shadow: 0 0 0 0 var(--bkq-support-ok); animation: bkq-support-beat 2s var(--bkq-support-out) infinite; }
@keyframes bkq-support-beat { 0% { box-shadow: 0 0 0 0 color-mix(in oklch, var(--bkq-support-ok) 60%, transparent); } 100% { box-shadow: 0 0 0 8px transparent; } }

.bkq-support-zones {
  display: flex; flex-wrap: wrap; justify-content: center; gap: 4px;
  padding: 4px; border-radius: 12px;
  background: var(--bkq-support-panel);
  border: 1px solid var(--bkq-support-line);
  & legend { position: absolute; width: 1px; height: 1px; overflow: hidden; clip-path: inset(50%); }
  & label { position: relative; cursor: pointer; }
  & input { position: absolute; inset: 0; opacity: 0; margin: 0; cursor: pointer; }
  & span {
    display: block; padding: 7px 11px; border-radius: 8px;
    font-size: 12.5px; font-weight: 560; color: var(--bkq-support-muted);
    transition: background-color .25s, color .25s;
  }
  & label:hover span { color: var(--bkq-support-ink); }
  & label:has(:checked) span { background: var(--bkq-support-ink); color: var(--bkq-support-bg); }
  & label:has(:focus-visible) span { outline: 2px solid var(--bkq-support-accent); outline-offset: 2px; }
}
.bkq-support-legend {
  list-style: none;
  display: grid; grid-template-columns: repeat(2, minmax(0, 1fr)); gap: 8px 18px;
  width: min(100%, 360px);
  & li { display: grid; grid-template-columns: 10px 1fr; column-gap: 8px; align-items: center; font-size: 13px; font-weight: 560; transition: opacity .3s; }
  & i { width: 10px; height: 10px; border-radius: 3px; }
  & span { grid-column: 2; font: 500 11px/1.3 ui-monospace, Menlo, monospace; color: var(--bkq-support-faint); }
  & [data-desk="lis"] i { background: var(--bkq-support-lis); }
  & [data-desk="tor"] i { background: var(--bkq-support-tor); }
  & [data-desk="sgp"] i { background: var(--bkq-support-sgp); }
  & [data-desk="oncall"] i { height: 3px; background: var(--bkq-support-call); }
}

/* ---- channel cards ---- */
.bkq-support-cards {
  grid-area: cards;
  list-style: none;
  display: grid; grid-template-columns: minmax(0, 1fr); gap: 10px;
  align-content: start;
}
.bkq-support-card {
  position: relative;
  display: grid;
  grid-template-columns: 36px minmax(0, 1fr) auto;
  grid-template-areas: "icon title link" "icon state link";
  align-items: center;
  gap: 2px 14px;
  padding: 14px 14px 14px 14px;
  border-radius: 14px;
  background: var(--bkq-support-panel);
  border: 1px solid var(--bkq-support-line);
  transition: border-color .25s, background-color .25s, translate .45s var(--bkq-support-spring), opacity .5s var(--bkq-support-out);
  transition-delay: 0s, 0s, 0s, calc(var(--i) * 60ms);
  @starting-style { opacity: 0; translate: 0 12px; }
  & > svg { grid-area: icon; width: 36px; height: 36px; padding: 7px; border-radius: 10px; background: var(--bkq-support-line); fill: none; stroke: var(--bkq-support-ink); stroke-width: 1.6; stroke-linecap: round; stroke-linejoin: round; }
  & h3 { grid-area: title; font-size: 16px; font-weight: 640; letter-spacing: -.01em; }
  & > p:not(.bkq-support-state) { grid-area: body; display: none; font-size: 13.5px; color: var(--bkq-support-muted); text-wrap: pretty; }
  & a {
    grid-area: link; justify-self: end;
    display: inline-flex; align-items: center; justify-content: center; gap: 6px;
    width: 32px; height: 32px; border-radius: 50%; border: 1px solid var(--bkq-support-line);
    font-size: 0; font-weight: 600; color: var(--bkq-support-ink); text-decoration: none;
    &::after { content: ""; position: absolute; inset: 0; border-radius: 14px; }
    &::before { content: "→"; order: 2; font-size: 15px; transition: translate .35s var(--bkq-support-spring); }
  }
  &:hover { border-color: color-mix(in oklch, var(--bkq-support-ink) 26%, var(--bkq-support-bg)); background: color-mix(in oklch, var(--bkq-support-ink) 7%, var(--bkq-support-bg)); translate: 0 -2px; & a::before { translate: 3px 0; } }
  &:has(a:focus-visible) { outline: 2px solid var(--bkq-support-accent); outline-offset: 2px; & a { outline: none; } }
}
.bkq-support-state {
  grid-area: state;
  display: inline-flex; align-items: center; gap: 7px;
  font: 600 11.5px/1.2 ui-monospace, Menlo, monospace; letter-spacing: .02em;
  font-variant-numeric: tabular-nums;
  color: var(--bkq-support-muted);
  &::before { content: ""; width: 7px; height: 7px; border-radius: 50%; flex: none; background: var(--bkq-support-faint); }
  &[data-state="open"] { color: var(--bkq-support-ok); &::before { background: var(--bkq-support-ok); box-shadow: 0 0 10px var(--bkq-support-ok); } }
  &[data-state="always"] { color: var(--bkq-support-ink); &::before { background: var(--bkq-support-ink); } }
  &[data-state="closed"] { color: var(--bkq-support-accent); &::before { background: transparent; border: 1.5px solid var(--bkq-support-accent); } }
}

/* hovering or focusing a channel isolates the desks that answer it */
.bkq-support:has(.bkq-support-card:is(:hover, :focus-within)) :is(.bkq-support-arc, .bkq-support-legend li) { opacity: .14; }
.bkq-support:has(.bkq-support-card[data-desks~="lis"]:is(:hover, :focus-within)) :is(.bkq-support-arc, .bkq-support-legend li)[data-desk="lis"],
.bkq-support:has(.bkq-support-card[data-desks~="tor"]:is(:hover, :focus-within)) :is(.bkq-support-arc, .bkq-support-legend li)[data-desk="tor"],
.bkq-support:has(.bkq-support-card[data-desks~="sgp"]:is(:hover, :focus-within)) :is(.bkq-support-arc, .bkq-support-legend li)[data-desk="sgp"],
.bkq-support:has(.bkq-support-card[data-desks~="oncall"]:is(:hover, :focus-within)) :is(.bkq-support-arc, .bkq-support-legend li)[data-desk="oncall"] { opacity: 1; stroke-width: 12; }
.bkq-support:has(.bkq-support-card[data-desks~="oncall"]:is(:hover, :focus-within)) .bkq-support-arc[data-desk="oncall"] { stroke-width: 5; }

@container bkq-support (min-width: 560px) {
  .bkq-support-cards { grid-template-columns: repeat(2, minmax(0, 1fr)); }
  .bkq-support-card { grid-template-columns: minmax(0, 1fr); grid-template-areas: "icon" "title" "body" "state" "link"; grid-template-rows: auto auto 1fr auto auto; align-items: start; gap: 6px; padding: 18px 18px 16px; }
  .bkq-support-card > svg { margin-bottom: 8px; }
  .bkq-support-card > p:not(.bkq-support-state) { display: block; }
  .bkq-support-state { margin-top: 6px; }
  .bkq-support-card a { justify-self: start; width: auto; height: auto; border: 0; border-radius: inherit; font-size: 13.5px; margin-top: 8px; }
}
@container bkq-support (min-width: 940px) {
  .bkq-support-in {
    grid-template-columns: minmax(300px, 4fr) minmax(0, 8fr);
    grid-template-areas: "head head" "dial cards";
    column-gap: clamp(32px, 5cqi, 72px);
  }
  .bkq-support-head { grid-template-columns: minmax(0, 1.2fr) minmax(0, 1fr); align-items: end; column-gap: 48px; }
  .bkq-support-brand { grid-column: 1 / -1; }
  .bkq-support-cards { grid-template-columns: repeat(3, minmax(0, 1fr)); }
}

@media (prefers-reduced-motion: reduce) {
  .bkq-support-svg .bkq-support-arcs, .bkq-support-svg .bkq-support-hand { transition: none; }
  .bkq-support-svg .bkq-support-arc { transition: opacity .2s; }
  .bkq-support-card { transition: border-color .2s, background-color .2s; translate: none !important; }
  .bkq-support[data-live] .bkq-support-staffed i { animation: none; }
}

