// Per-instance id suffix so aria references survive the section being pasted twice.
const iid = Math.random().toString(36).slice(2, 7);
root.querySelectorAll('[id]').forEach((n) => { n.id += '-' + iid; });
['aria-controls', 'aria-describedby', 'aria-labelledby'].forEach((a) => root.querySelectorAll('[' + a + ']').forEach((n) => {
  n.setAttribute(a, n.getAttribute(a).split(' ').map((s) => s + '-' + iid).join(' '));
}));
if (root.hasAttribute('aria-labelledby')) root.setAttribute('aria-labelledby', root.getAttribute('aria-labelledby') + '-' + iid);
const NS = 'http://www.w3.org/2000/svg';
const doc = root.ownerDocument;
const C = 160;
const DESKS = {
  lis: { name: 'Lisbon', tz: 'Europe/Lisbon', open: 8 * 60, close: 17 * 60 },
  tor: { name: 'Toronto', tz: 'America/Toronto', open: 9 * 60, close: 18 * 60 },
  sgp: { name: 'Singapore', tz: 'Asia/Singapore', open: 8 * 60, close: 17 * 60 },
};
const RING = { lis: 128, tor: 113, sgp: 98, oncall: 84 };

// The radio group name must be unique per instance, or two pasted copies share one group.
const group = 'bkq-support-z-' + Math.random().toString(36).slice(2, 7);
const radios = [...root.querySelectorAll('.bkq-support-zones input')];
radios.forEach((r) => { r.name = group; });

const el = (tag, attrs) => { const n = doc.createElementNS(NS, tag); for (const k in attrs) n.setAttribute(k, attrs[k]); return n; };
const pt = (deg, r) => { const a = (deg - 90) * Math.PI / 180; return [C + r * Math.cos(a), C + r * Math.sin(a)]; };
const f = (n) => n.toFixed(2);

// Minutes east of UTC for a zone at a given instant, DST included.
function tzOffset(tz, at) {
  if (tz === 'local') return -at.getTimezoneOffset();
  const p = {};
  new Intl.DateTimeFormat('en-US', { timeZone: tz, hourCycle: 'h23', year: 'numeric', month: 'numeric', day: 'numeric', hour: 'numeric', minute: 'numeric' })
    .formatToParts(at).forEach((x) => { p[x.type] = x.value; });
  const asUTC = Date.UTC(+p.year, +p.month - 1, +p.day, +p.hour % 24, +p.minute);
  return Math.round((asUTC - Math.floor(at.getTime() / 60000) * 60000) / 60000);
}

// ---- static dial furniture: 15-minute ticks, hour labels, the night band (18:00 to 06:00) ----
const ticks = root.querySelector('.bkq-support-ticks');
for (let q = 0; q < 96; q++) {
  const deg = q * 3.75, hr = q % 4 === 0;
  const [x1, y1] = pt(deg, hr ? 139 : 141.5), [x2, y2] = pt(deg, 146);
  const ln = el('line', { x1: f(x1), y1: f(y1), x2: f(x2), y2: f(y2) });
  if (hr) ln.classList.add('bkq-support-hr');
  ticks.append(ln);
  if (q % 12 === 0) {
    const [tx, ty] = pt(deg, 157);
    const t = el('text', { x: f(tx), y: f(ty) });
    t.textContent = String(q / 4).padStart(2, '0');
    ticks.append(t);
  }
}
(() => {
  const [ax, ay] = pt(270, 135), [bx, by] = pt(90, 135), [cx, cy] = pt(90, 76), [dx, dy] = pt(270, 76);
  root.querySelector('.bkq-support-night').setAttribute('d',
    `M${f(ax)} ${f(ay)} A135 135 0 0 1 ${f(bx)} ${f(by)} L${f(cx)} ${f(cy)} A76 76 0 0 0 ${f(dx)} ${f(dy)} Z`);
})();

// ---- desk arcs, drawn in UTC minutes; the group is rotated into whichever zone is chosen ----
const arcs = root.querySelector('.bkq-support-arcs');
function arcPath(m0, m1, r) {
  const span = ((m1 - m0) % 1440 + 1440) % 1440;
  const a0 = m0 / 4, a1 = a0 + span / 4;
  const [x0, y0] = pt(a0, r), [x1, y1] = pt(a1, r);
  return `M${f(x0)} ${f(y0)} A${r} ${r} 0 ${span > 720 ? 1 : 0} 1 ${f(x1)} ${f(y1)}`;
}
function buildArcs(now) {
  arcs.textContent = '';
  let i = 0;
  for (const id in DESKS) {
    const d = DESKS[id];
    const off = tzOffset(d.tz, now);
    const p = el('path', { d: arcPath(d.open - off, d.close - off, RING[id]), pathLength: 1, 'data-desk': id });
    p.classList.add('bkq-support-arc');
    p.style.setProperty('--i', i++);
    arcs.append(p);
  }
  const on = el('circle', { cx: C, cy: C, r: RING.oncall, 'data-desk': 'oncall' });
  on.classList.add('bkq-support-arc');
  arcs.append(on);
}

// ---- live state ----
const clock = root.querySelector('.bkq-support-clock');
const zoneLabel = root.querySelector('.bkq-support-zone');
const staffed = root.querySelector('.bkq-support-n');
const cards = [...root.querySelectorAll('.bkq-support-card')];
const localTz = (Intl.DateTimeFormat().resolvedOptions().timeZone || '').split('/').pop().replace(/_/g, ' ');
const day0 = Math.floor(Date.now() / 86400000) * 1440;   // UTC midnight today, in minutes
let zone = 'local';

function deskNow(d, now) {
  const local = new Date(now.getTime() + tzOffset(d.tz, now) * 60000);
  const wd = local.getUTCDay(), m = local.getUTCHours() * 60 + local.getUTCMinutes();
  const open = wd >= 1 && wd <= 5 && m >= d.open && m < d.close;
  let wait = Infinity;
  if (!open) {
    for (let k = 0; k < 8; k++) {
      const dd = (wd + k) % 7;
      if (dd === 0 || dd === 6) continue;
      if (k === 0 && m >= d.open) continue;
      wait = k * 1440 + d.open - m; break;
    }
  }
  return { open, wait };
}
// Under twelve hours reads as a countdown; further out, as the opening time on your own clock.
const fmtWait = (w, now) => {
  const h = Math.floor(w / 60), m = w % 60;
  if (h < 12) return ('Opens in ' + (h ? h + ' h ' : '') + (m || !h ? m + ' min' : '')).trim();
  const at = new Date(now.getTime() + w * 60000);
  return 'Opens ' + new Intl.DateTimeFormat('en-GB', { weekday: 'short', hour: '2-digit', minute: '2-digit', hourCycle: 'h23' }).format(at).replace(',', '') + ' your time';
};

function update() {
  const now = new Date();
  const off = tzOffset(zone, now);
  const utcMin = Math.floor(now.getTime() / 60000) - day0;
  root.style.setProperty('--bkq-support-z', off / 4 + 'deg');
  root.style.setProperty('--bkq-support-a', (utcMin + off) / 4 + 'deg');
  const loc = new Date(now.getTime() + off * 60000);
  clock.textContent = String(loc.getUTCHours()).padStart(2, '0') + ':' + String(loc.getUTCMinutes()).padStart(2, '0');
  zoneLabel.textContent = zone === 'local' ? 'Your time' + (localTz ? ' · ' + localTz : '') : zone.split('/').pop() + ' time';

  const st = {};
  let n = 0;
  for (const id in DESKS) { st[id] = deskNow(DESKS[id], now); if (st[id].open) n++; }
  staffed.textContent = n;
  root.toggleAttribute('data-live', n > 0);

  cards.forEach((c) => {
    const ids = c.dataset.desks.split(' ').filter((id) => DESKS[id]);
    if (!ids.length) return;
    const s = c.querySelector('.bkq-support-state');
    const open = ids.filter((id) => st[id].open);
    if (open.length) {
      s.dataset.state = 'open';
      s.textContent = 'Open now · ' + open.map((id) => DESKS[id].name).join(' & ');
    } else {
      s.dataset.state = 'closed';
      s.textContent = fmtWait(Math.min(...ids.map((id) => st[id].wait)), now);
    }
  });
}

radios.forEach((r) => r.addEventListener('change', () => { zone = r.value; update(); }));

buildArcs(new Date());
update();

// Tick every 20 s, skipping work while the tab is hidden or the dial is off screen.
let visible = true;
const io = new IntersectionObserver(([e]) => { visible = e.isIntersecting; if (visible) update(); });
io.observe(root);
let lastDay = Math.floor(Date.now() / 86400000);
const timer = setInterval(() => {
  if (!root.isConnected) { clearInterval(timer); io.disconnect(); return; }
  if (doc.hidden || !visible) return;
  const d = Math.floor(Date.now() / 86400000);
  if (d !== lastDay) { lastDay = d; buildArcs(new Date()); }
  update();
}, 20000);

css:
.bkq-chat {
  /* re-theme with these four */
  --bkq-chat-bg: oklch(96.4% 0.028 92);
  --bkq-chat-ink: oklch(30% 0.065 158);
  --bkq-chat-accent: oklch(70% 0.155 42);
  --bkq-chat-leaf: oklch(64% 0.13 148);

  --bkq-chat-paper: color-mix(in oklch, white 82%, var(--bkq-chat-bg));
  --bkq-chat-muted: color-mix(in oklch, var(--bkq-chat-ink) 64%, var(--bkq-chat-bg));
  --bkq-chat-faint: color-mix(in oklch, var(--bkq-chat-ink) 38%, var(--bkq-chat-bg));
  --bkq-chat-line: color-mix(in oklch, var(--bkq-chat-ink) 12%, var(--bkq-chat-bg));
  --bkq-chat-tint: color-mix(in oklch, var(--bkq-chat-leaf) 16%, var(--bkq-chat-bg));
  --bkq-chat-warm: color-mix(in oklch, var(--bkq-chat-accent) 16%, var(--bkq-chat-bg));
  --bkq-chat-spring: linear(0, .006, .025 2.8%, .101 6.1%, .539 18.9%, .721 25.3%, .849 31.5%, .937 38.1%, .968 41.8%, .991 45.7%, 1.006 50.1%, 1.015 55%, 1.017 63.9%, 1.001 85.9%, 1);
  --bkq-chat-pop: linear(0, .045 1.6%, .18 3.6%, .64 9.8%, .86 13.6%, 1.03 18%, 1.11 22%, 1.13 25.6%, 1.11 29.6%, 1.03 38%, .99 46%, .985 55%, 1);
  --bkq-chat-out: cubic-bezier(.22, 1, .36, 1);
  --bkq-chat-gutter: clamp(16px, 5cqi, 64px);

  container-type: inline-size;
  container-name: bkq-chat;
  box-sizing: border-box;
  width: 100%;
  position: relative;
  overflow: hidden;
  background:
    radial-gradient(38cqi 38cqi at 96% 8%, color-mix(in oklch, var(--bkq-chat-accent) 20%, transparent), transparent 70%),
    radial-gradient(42cqi 42cqi at 0% 100%, color-mix(in oklch, var(--bkq-chat-leaf) 22%, transparent), transparent 70%),
    var(--bkq-chat-bg);
  color: var(--bkq-chat-ink);
  font: 400 15px/1.5 ui-rounded, system-ui, -apple-system, "Segoe UI", Roboto, sans-serif;
  -webkit-font-smoothing: antialiased;
  accent-color: var(--bkq-chat-leaf);

  & *, & *::before, & *::after { box-sizing: border-box; }
  & :where(h2, p, ul) { margin: 0; padding: 0; }
  & :where(button, input) { font: inherit; color: inherit; }
  & :focus-visible { outline: 2.5px solid var(--bkq-chat-accent); outline-offset: 2px; border-radius: 10px; }
}

.bkq-chat-in {
  display: grid;
  gap: 32px;
  grid-template-columns: minmax(0, 1fr);
  grid-template-areas: "head" "win";
  padding: clamp(36px, 6cqi, 80px) var(--bkq-chat-gutter);
  max-width: 1180px;
  margin-inline: auto;
}

.bkq-chat-head { grid-area: head; display: grid; gap: 16px; align-content: center; }
.bkq-chat-brand {
  display: flex; align-items: center; gap: 8px;
  & svg { width: 26px; height: 26px; fill: none; stroke: var(--bkq-chat-leaf); stroke-width: 1.8; stroke-linecap: round; stroke-linejoin: round; }
  & b { font-size: 20px; font-weight: 800; letter-spacing: -.04em; }
  & span {
    font-size: 12px; font-weight: 650; padding: 3px 9px; border-radius: 999px;
    background: var(--bkq-chat-ink); color: var(--bkq-chat-bg); letter-spacing: .01em;
  }
}
.bkq-chat-title {
  font-size: clamp(32px, 4cqi + 16px, 58px);
  line-height: 1; letter-spacing: -.04em; font-weight: 800;
  text-wrap: balance; max-width: 13ch;
}
.bkq-chat-lede { max-width: 44ch; color: var(--bkq-chat-muted); text-wrap: pretty; font-size: clamp(15px, .4cqi + 13.6px, 17px); }
.bkq-chat-facts {
  list-style: none;
  display: grid; grid-template-columns: repeat(3, minmax(0, 1fr)); gap: 10px;
  margin-top: 6px;
  & li {
    display: grid; gap: 2px; align-content: start;
    padding: 14px 12px; border-radius: 18px;
    background: color-mix(in oklch, var(--bkq-chat-paper) 70%, transparent);
    border: 1.5px solid var(--bkq-chat-line);
  }
  & li:nth-child(2) { rotate: -1.5deg; background: var(--bkq-chat-warm); }
  & b { font-size: clamp(20px, 1.6cqi + 12px, 28px); font-weight: 800; letter-spacing: -.03em; font-variant-numeric: tabular-nums; line-height: 1.1; }
  & span { font-size: 12.5px; line-height: 1.35; color: var(--bkq-chat-muted); }
}

/* ---- chat window ---- */
.bkq-chat-win {
  grid-area: win;
  display: grid; grid-template-rows: auto minmax(0, 1fr) auto;
  height: 560px;
  width: 100%; max-width: 560px;
  border-radius: 30px;
  background: var(--bkq-chat-paper);
  border: 1.5px solid var(--bkq-chat-line);
  box-shadow: 0 2px 0 color-mix(in oklch, var(--bkq-chat-ink) 6%, transparent), 0 30px 60px -30px color-mix(in oklch, var(--bkq-chat-ink) 35%, transparent);
  overflow: hidden;
}
.bkq-chat-bar {
  display: flex; align-items: center; gap: 12px;
  padding: 14px 14px 14px 16px;
  border-bottom: 1.5px solid var(--bkq-chat-line);
}
.bkq-chat-av {
  width: 40px; height: 40px; flex: none;
  display: grid; place-items: center;
  border-radius: 14px;
  background: var(--bkq-chat-tint);
  rotate: -4deg;
  & svg { width: 24px; height: 24px; fill: none; stroke: var(--bkq-chat-ink); stroke-width: 1.8; stroke-linecap: round; stroke-linejoin: round; }
}
.bkq-chat-who {
  display: grid; line-height: 1.25; min-width: 0;
  & b { font-size: 15.5px; font-weight: 750; }
  & small { display: flex; align-items: center; gap: 6px; font-size: 12px; color: var(--bkq-chat-muted); white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
  & i { width: 7px; height: 7px; flex: none; border-radius: 50%; background: var(--bkq-chat-leaf); box-shadow: 0 0 0 3px color-mix(in oklch, var(--bkq-chat-leaf) 25%, transparent); }
}
.bkq-chat-restart {
  margin-left: auto; flex: none;
  width: 38px; height: 38px; display: grid; place-items: center;
  border: 1.5px solid var(--bkq-chat-line); border-radius: 12px; background: none; cursor: pointer;
  transition: background-color .2s, rotate .6s var(--bkq-chat-spring);
  & svg { width: 18px; height: 18px; fill: none; stroke: currentColor; stroke-width: 2; stroke-linecap: round; stroke-linejoin: round; }
  &:hover { background: var(--bkq-chat-tint); rotate: -40deg; }
}

.bkq-chat-log {
  overflow-y: auto; overscroll-behavior: contain;
  padding: 18px 16px 10px;
  display: flex; flex-direction: column; gap: 6px;
  scrollbar-width: thin; scrollbar-color: var(--bkq-chat-line) transparent;
  &:focus-visible { outline-offset: -3px; border-radius: 0; }
}
.bkq-chat-msg {
  display: flex; flex-direction: column; align-items: flex-start; gap: 3px;
  max-width: 86%;
  &[data-from="user"] { align-self: flex-end; align-items: flex-end; }
}
.bkq-chat-msg[data-from="bot"] + .bkq-chat-msg[data-from="user"], .bkq-chat-msg[data-from="user"] + .bkq-chat-msg[data-from="bot"] { margin-top: 10px; }
.bkq-chat-bub {
  padding: 10px 14px;
  border-radius: 20px 20px 20px 6px;
  background: var(--bkq-chat-bg);
  font-size: 14.5px; line-height: 1.45;
  text-wrap: pretty;
  transform-origin: 0 100%;
  transition: opacity .3s var(--bkq-chat-out), scale .55s var(--bkq-chat-pop), translate .55s var(--bkq-chat-pop);
  @starting-style { opacity: 0; scale: .7; translate: -6px 8px; }
  & b { font-weight: 700; }
  .bkq-chat-msg[data-from="user"] & {
    border-radius: 20px 20px 6px 20px;
    background: var(--bkq-chat-ink); color: var(--bkq-chat-bg);
    transform-origin: 100% 100%;
    @starting-style { opacity: 0; scale: .7; translate: 6px 8px; }
  }
  & svg { width: 18px; height: 18px; vertical-align: -4px; margin-right: 6px; fill: none; stroke: currentColor; stroke-width: 1.7; stroke-linecap: round; stroke-linejoin: round; }
}
.bkq-chat-card {
  display: grid; gap: 6px;
  padding: 14px 16px;
  border-radius: 20px 20px 20px 6px;
  background: var(--bkq-chat-tint);
  border: 1.5px dashed color-mix(in oklch, var(--bkq-chat-leaf) 45%, var(--bkq-chat-bg));
  font-size: 14px; line-height: 1.5;
  transform-origin: 0 100%;
  transition: opacity .3s var(--bkq-chat-out), scale .55s var(--bkq-chat-pop);
  @starting-style { opacity: 0; scale: .8; }
  & strong { display: flex; align-items: center; gap: 6px; font-size: 11.5px; font-weight: 800; letter-spacing: .08em; text-transform: uppercase; color: color-mix(in oklch, var(--bkq-chat-leaf) 70%, var(--bkq-chat-ink)); }
  & strong svg { width: 16px; height: 16px; fill: none; stroke: currentColor; stroke-width: 2; stroke-linecap: round; stroke-linejoin: round; }
}
.bkq-chat-edit {
  display: inline-flex; align-items: center; gap: 4px;
  padding: 2px 6px; border: 0; border-radius: 6px; background: none; cursor: pointer;
  font-size: 11.5px; font-weight: 650; color: var(--bkq-chat-faint);
  transition: color .2s, background-color .2s;
  & svg { width: 12px; height: 12px; fill: none; stroke: currentColor; stroke-width: 2; stroke-linecap: round; stroke-linejoin: round; }
  &:hover { color: var(--bkq-chat-ink); background: var(--bkq-chat-tint); }
}
.bkq-chat-typing .bkq-chat-bub {
  display: flex; gap: 4px; padding: 14px 16px;
  & i { width: 7px; height: 7px; border-radius: 50%; background: var(--bkq-chat-faint); animation: bkq-chat-dot 1s var(--bkq-chat-out) infinite; animation-delay: calc(var(--d) * 140ms); }
  & i:nth-child(1) { --d: 0; } & i:nth-child(2) { --d: 1; } & i:nth-child(3) { --d: 2; }
}
@keyframes bkq-chat-dot { 0%, 60%, 100% { translate: 0 0; opacity: .5; } 30% { translate: 0 -4px; opacity: 1; } }

/* ---- composer ---- */
.bkq-chat-compose { border-top: 1.5px solid var(--bkq-chat-line); padding: 12px 14px 14px; min-height: 68px; display: grid; align-content: center; }
.bkq-chat-quick {
  display: flex; flex-wrap: wrap; justify-content: flex-end; gap: 6px;
  &:empty { display: none; }
  & button {
    display: inline-flex; align-items: center; gap: 6px;
    min-height: 38px; padding: 7px 14px;
    border: 1.5px solid var(--bkq-chat-ink); border-radius: 999px;
    background: var(--bkq-chat-paper);
    font-size: 13.5px; font-weight: 650;
    cursor: pointer;
    transition: background-color .2s, color .2s, translate .45s var(--bkq-chat-pop), opacity .35s var(--bkq-chat-out), scale .45s var(--bkq-chat-pop);
    transition-delay: 0s, 0s, 0s, calc(var(--i) * 55ms), calc(var(--i) * 55ms);
    @starting-style { opacity: 0; scale: .6; }
    &:hover { background: var(--bkq-chat-ink); color: var(--bkq-chat-bg); translate: 0 -2px; }
    &:active { scale: .95; }
    & svg { width: 20px; height: 20px; fill: none; stroke: currentColor; stroke-width: 1.6; stroke-linecap: round; stroke-linejoin: round; }
  }
}
.bkq-chat-form {
  display: grid; grid-template-columns: minmax(0, 1fr) auto; gap: 4px 8px; align-items: center;
  &[hidden] { display: none; }
}
.bkq-chat-text {
  height: 44px; padding: 0 16px;
  border: 1.5px solid var(--bkq-chat-line); border-radius: 999px;
  background: var(--bkq-chat-bg);
  font-size: 15px;
  outline: none;
  transition: border-color .2s, box-shadow .2s;
  &:focus { border-color: var(--bkq-chat-ink); box-shadow: 0 0 0 4px color-mix(in oklch, var(--bkq-chat-leaf) 22%, transparent); }
  &[aria-invalid="true"] { border-color: var(--bkq-chat-accent); }
}
.bkq-chat-send {
  width: 44px; height: 44px; display: grid; place-items: center;
  border: 0; border-radius: 50%; background: var(--bkq-chat-ink); color: var(--bkq-chat-bg); cursor: pointer;
  transition: scale .4s var(--bkq-chat-pop), background-color .2s;
  & svg { width: 20px; height: 20px; fill: none; stroke: currentColor; stroke-width: 2.2; stroke-linecap: round; stroke-linejoin: round; }
  &:hover { scale: 1.06; background: color-mix(in oklch, var(--bkq-chat-ink) 85%, var(--bkq-chat-leaf)); }
  &:active { scale: .92; }
}
.bkq-chat-err { grid-column: 1 / -1; padding-left: 16px; font-size: 12.5px; font-weight: 600; color: color-mix(in oklch, var(--bkq-chat-accent) 75%, var(--bkq-chat-ink)); &:empty { display: none; } }
.bkq-chat-sr { position: absolute; width: 1px; height: 1px; overflow: hidden; clip-path: inset(50%); white-space: nowrap; }

@container bkq-chat (max-width: 420px) {
  .bkq-chat-facts { grid-template-columns: minmax(0, 1fr); & li { grid-template-columns: 64px 1fr; align-items: baseline; padding: 10px 14px; } & li:nth-child(2) { rotate: none; } }
  .bkq-chat-win { height: 540px; border-radius: 24px; }
  .bkq-chat-msg { max-width: 92%; }
}
@container bkq-chat (min-width: 860px) {
  .bkq-chat-in {
    grid-template-columns: minmax(0, 1fr) minmax(380px, 440px);
    grid-template-areas: "head win";
    column-gap: clamp(40px, 7cqi, 110px);
    align-items: center;
  }
  .bkq-chat-win { rotate: 1deg; transition: rotate .8s var(--bkq-chat-spring); &:focus-within, &:hover { rotate: 0deg; } }
}

@media (prefers-reduced-motion: reduce) {
  .bkq-chat-bub, .bkq-chat-card, .bkq-chat-quick button { transition: background-color .2s, color .2s; }
  .bkq-chat-typing .bkq-chat-bub i { animation: none; opacity: .7; }
  .bkq-chat-win, .bkq-chat-restart { transition: none; rotate: none !important; }
}

js:
const doc = root.ownerDocument;
const reduce = matchMedia('(prefers-reduced-motion: reduce)');
const uid = Math.random().toString(36).slice(2, 7);
root.querySelectorAll('[id]').forEach((n) => { n.id += '-' + uid; });
root.querySelectorAll('[for], [aria-labelledby]').forEach((n) => {
  ['for', 'aria-labelledby'].forEach((a) => { if (n.hasAttribute(a)) n.setAttribute(a, n.getAttribute(a) + '-' + uid); });
});
if (root.hasAttribute('aria-labelledby')) root.setAttribute('aria-labelledby', root.getAttribute('aria-labelledby') + '-' + uid);

const log = root.querySelector('.bkq-chat-log');
const quick = root.querySelector('.bkq-chat-quick');
const form = root.querySelector('.bkq-chat-form');
const text = root.querySelector('.bkq-chat-text');
const err = root.querySelector('.bkq-chat-err');

const ICON = {
  monstera: '<svg viewBox="0 0 24 24" aria-hidden="true"><path d="M12 21v-8"/><path d="M12 13c-5 0-8-3-8-8 3-1.2 6-.3 8 2 2-2.3 5-3.2 8-2 0 5-3 8-8 8z"/><path d="m7.5 7.5 2 2.5M16.5 7.5l-2 2.5M12 7v3"/></svg>',
  calathea: '<svg viewBox="0 0 24 24" aria-hidden="true"><path d="M12 21v-4"/><path d="M12 17C7.5 16 5.5 11 7 4c3.5 1.5 5.5 6 5 13z"/><path d="M12 17c4.5-1 6.5-6 5-13-3.5 1.5-5.5 6-5 13z"/><path d="M8.2 8.5 10 10M15.8 8.5 14 10"/></svg>',
  pothos: '<svg viewBox="0 0 24 24" aria-hidden="true"><path d="M6 10h10l-1.4 9H7.4z"/><path d="M9 10c0-3 1-5 3-6"/><path d="M16 12c2.5.5 3.5 2.5 3.5 5"/><path d="M19.5 17c-1.3.2-2.2-.6-2-1.8 1.3-.2 2.2.6 2 1.8z"/><path d="M12 4c1.5-.5 3 0 3.5 1.5-1.5.5-3 0-3.5-1.5z"/></svg>',
  fig: '<svg viewBox="0 0 24 24" aria-hidden="true"><path d="M12 21V7"/><path d="M12 9c-2.5-.5-4-2.2-4-4.5 2.5 0 4 1.8 4 4.5z"/><path d="M12 13c2.8-.4 4.5-2.3 4.5-5-2.8.2-4.5 2.2-4.5 5z"/><path d="M12 17c-2.8-.4-4.5-2.3-4.5-5 2.8.2 4.5 2.2 4.5 5z"/><path d="M9 21h6"/></svg>',
  leaf: '<svg viewBox="0 0 24 24" aria-hidden="true"><path d="M5 19c0-8 5-13 14-14 0 9-5 14-14 14z"/><path d="M5 19 13 11"/></svg>',
  edit: '<svg viewBox="0 0 24 24" aria-hidden="true"><path d="M4 20h4L19 9l-4-4L4 16z"/></svg>',
};
const PLANTS = { monstera: 'Monstera', calathea: 'Calathea', pothos: 'Pothos', fig: 'Fiddle-leaf fig' };
const CURE = {
  yellow: 'Yellowing lower leaves usually mean too much water. Let the top 3 cm of soil dry before the next drink, and tip out any water left in the cover pot.',
  tips: 'Brown, crispy tips are dry air or hard tap water. Group it with other plants, move it away from the radiator and water with filtered or rain water for a month.',
  droop: 'Drooping with dry soil is thirst: stand it in water for 20 minutes, then drain. Drooping with wet soil means the roots need air, so skip watering for a week.',
  spots: 'Brown spots with a yellow halo are often fungal. Snip those leaves with clean scissors and keep water off the foliage for two weeks.',
};

const esc = (v) => { const n = doc.createElement('span'); n.textContent = v; return n.innerHTML; };
const fmtDay = (d) => new Intl.DateTimeFormat('en-GB', { weekday: 'long', day: 'numeric', month: 'long' }).format(d);
const nextBox = (() => {      // boxes ship every other Thursday; the next one is at least two days away
  const d = new Date(); d.setHours(12, 0, 0, 0);
  do d.setDate(d.getDate() + 1); while (d.getDay() !== 4 || (d - Date.now()) < 2 * 864e5 - 12 * 36e5);
  return d;
})();
const plus = (days) => { const d = new Date(nextBox); d.setDate(d.getDate() + days); return d; };

// answers[k] = { step, value, label }; each step knows what Juno says and how you can reply.
let answers = [];
const val = (step) => (answers.find((a) => a.step === step) || {}).value;

const STEPS = {
  start: {
    say: () => ['Hi, I’m Juno from the Sprig plant desk.', 'What can I help with today?'],
    quick: () => [['unwell', 'A plant looks unwell'], ['delivery', 'Change my delivery'], ['other', 'Something else']],
    next: (v) => v,
  },
  unwell: {
    say: () => ['Sorry to hear it. Which plant is it?'],
    quick: () => Object.keys(PLANTS).map((k) => [k, PLANTS[k], ICON[k]]),
    next: () => 'symptom',
  },
  symptom: {
    say: () => ['And what are you seeing on your ' + PLANTS[val('unwell')].toLowerCase() + '?'],
    quick: () => [['yellow', 'Yellow leaves'], ['tips', 'Brown crispy tips'], ['droop', 'Drooping'], ['spots', 'Spots']],
    next: () => 'advice',
  },
  advice: {
    say: () => [{ card: CURE[val('symptom')] }, 'Want a botanist to look at it too? I’ll pass this whole chat along.'],
    quick: () => [['yes', 'Yes, ask a botanist'], ['no', 'That should do it']],
    next: (v) => (v === 'yes' ? 'email' : 'bye'),
  },
  delivery: {
    say: () => ['Your next box ships on <b>' + fmtDay(nextBox) + '</b>. What would you like to do?'],
    quick: () => [['skip', 'Skip this box'], ['move', 'Send it a week later'], ['address', 'Change the address']],
    next: (v) => (v === 'address' ? 'email' : 'done'),
  },
  other: {
    say: () => ['Tell me in a sentence and I’ll find the right person.'],
    input: { type: 'text', placeholder: 'My order arrived without a pot…', check: (v) => (v.trim().length >= 8 ? '' : 'A few more words, please.') },
    next: () => 'email',
  },
  email: {
    say: () => ['What’s the best email for the reply?'],
    input: { type: 'email', placeholder: 'you@yourmail.com', check: (v) => (/^[^\s@]+@[^\s@]+\.[a-z]{2,}$/i.test(v.trim()) ? '' : 'That email looks incomplete.') },
    next: () => 'done',
  },
  bye: {
    say: () => ['Lovely. If it’s still sulking in a week, come back here: you can edit any answer above.'],
    quick: () => [['restart', 'Start a new chat']],
  },
  done: {
    say: () => {
      const ref = 'SPR-' + (4000 + Math.floor(Math.random() * 5000));
      const email = esc(val('email') || '');
      if (val('start') === 'unwell') return ['Done. Ticket <b>' + ref + '</b> is with Mateo, who looks after ' + PLANTS[val('unwell')].toLowerCase() + ' care. Expect a reply at <b>' + email + '</b> within 2 hours, with a link to add photos.'];
      if (val('delivery') === 'skip') return ['Skipped. Nothing ships on ' + fmtDay(nextBox) + ' and you won’t be charged the £24 for it. Your next box is <b>' + fmtDay(plus(14)) + '</b>.'];
      if (val('delivery') === 'move') return ['Moved. It now ships on <b>' + fmtDay(plus(7)) + '</b>, and the fortnightly rhythm carries on from there.'];
      if (val('delivery') === 'address') return ['I’ve sent a secure link to <b>' + email + '</b>. It changes the address for every future box and works for 24 hours.'];
      return ['Thanks. Ticket <b>' + ref + '</b> is with our care team, and they’ll reply to <b>' + email + '</b> within 2 hours.'];
    },
    quick: () => [['restart', 'Start a new chat']],
  },
};

let run = 0;          // bumps on every rewind so stale typing timers do nothing
let interacted = false;
const wait = (ms) => new Promise((r) => setTimeout(r, reduce.matches ? 0 : ms));
const toBottom = () => log.scrollTo({ top: log.scrollHeight, behavior: reduce.matches ? 'auto' : 'smooth' });

function msg(from, html, k, role) {
  const m = doc.createElement('div');
  m.className = 'bkq-chat-msg';
  m.dataset.from = from; m.dataset.step = k; m.dataset.role = role;
  if (typeof html === 'object') {
    m.innerHTML = '<div class="bkq-chat-card"><strong>' + ICON.leaf + 'Juno’s first aid</strong><span></span></div>';
    m.querySelector('span').textContent = html.card;
  } else {
    m.innerHTML = '<p class="bkq-chat-bub">' + html + '</p>';
  }
  if (from === 'user') {
    const b = doc.createElement('button');
    b.type = 'button'; b.className = 'bkq-chat-edit'; b.dataset.k = k;
    b.innerHTML = ICON.edit + 'Edit';
    b.setAttribute('aria-label', 'Change this answer');
    m.append(b);
  }
  log.append(m);
  toBottom();
  return m;
}

async function ask(k) {
  const id = k === 0 ? 'start' : STEPS[answers[k - 1].step].next(answers[k - 1].value);
  const step = STEPS[id];
  const mine = run;
  clearInput();
  for (const line of step.say()) {
    const t = msg('bot', '<i></i><i></i><i></i>', k, 'typing');
    t.classList.add('bkq-chat-typing');
    await wait(typeof line === 'object' ? 1100 : 420 + Math.min(String(line).length * 9, 700));
    t.remove();
    if (mine !== run) return;
    msg('bot', line, k, 'prompt');
  }
  if (mine !== run) return;
  showInput(id, k);
}

function clearInput() { quick.textContent = ''; form.hidden = true; err.textContent = ''; }

function showInput(id, k) {
  const step = STEPS[id];
  if (step.quick) {
    step.quick().forEach(([v, label, icon], i) => {
      const b = doc.createElement('button');
      b.type = 'button';
      b.style.setProperty('--i', i);
      b.tabIndex = i === 0 ? 0 : -1;
      b.innerHTML = (icon || '') + '<span></span>';
      b.querySelector('span').textContent = label;
      b.addEventListener('click', () => (v === 'restart' ? rewind(0) : answer(k, id, v, label, icon)));
      quick.append(b);
    });
    if (interacted) quick.firstElementChild.focus({ preventScroll: true });
  } else {
    form.hidden = false;
    form.dataset.k = k; form.dataset.id = id;
    text.type = step.input.type; text.placeholder = step.input.placeholder; text.value = '';
    text.setAttribute('aria-invalid', 'false');
    if (interacted) text.focus({ preventScroll: true });
  }
}

function answer(k, id, value, label, icon) {
  interacted = true;
  answers = answers.slice(0, k);
  answers.push({ step: id, value, label });
  msg('user', (icon || '') + esc(label), k, 'answer');
  ask(k + 1);
}

form.addEventListener('submit', (e) => {
  e.preventDefault();
  const id = form.dataset.id, k = +form.dataset.k;
  const problem = STEPS[id].input.check(text.value);
  err.textContent = problem;
  text.setAttribute('aria-invalid', String(!!problem));
  if (problem) { text.focus(); return; }
  answer(k, id, text.value.trim(), text.value.trim());
});
text.addEventListener('input', () => { if (err.textContent) { err.textContent = ''; text.setAttribute('aria-invalid', 'false'); } });

// Rewind: later bubbles fold away (fade, then height to zero) before the question is asked again.
async function rewind(k) {
  run++;
  interacted = true;
  clearInput();
  answers = answers.slice(0, k);
  const gone = [...log.children].filter((m) => +m.dataset.step > k || (+m.dataset.step === k && m.dataset.role !== 'prompt'));
  if (!reduce.matches && gone.length) {
    const anims = gone.reverse().map((m, i) => {
      const h = m.offsetHeight;
      m.style.overflow = 'hidden';
      return m.animate([
        { opacity: 1, height: h + 'px', transform: 'none' },
        { opacity: 0, height: h + 'px', transform: 'translateY(6px) scale(.94)', offset: .55 },
        { opacity: 0, height: '0px', marginTop: '0px', transform: 'scale(.9)' },
      ], { duration: 420, delay: Math.min(i, 8) * 35, easing: 'cubic-bezier(.4, 0, .2, 1)', fill: 'forwards' }).finished;
    });
    const mine = run;
    await Promise.all(anims);
    if (mine !== run) return;
  }
  gone.forEach((m) => m.remove());
  if (k === 0 && !log.children.length) { ask(0); return; }
  if (log.querySelector('[data-role="prompt"][data-step="' + k + '"]')) {
    const id = k === 0 ? 'start' : STEPS[answers[k - 1].step].next(answers[k - 1].value);
    showInput(id, k);
    toBottom();
  } else ask(k);
}

log.addEventListener('click', (e) => {
  const b = e.target.closest('.bkq-chat-edit');
  if (b) rewind(+b.dataset.k);
});
root.querySelector('.bkq-chat-restart').addEventListener('click', () => rewind(0));

// Quick replies are one tab stop; arrows move between them.
quick.addEventListener('keydown', (e) => {
  const bs = [...quick.querySelectorAll('button')];
  const i = bs.indexOf(doc.activeElement);
  if (i < 0) return;
  let n = null;
  if (e.key === 'ArrowRight' || e.key === 'ArrowDown') n = bs[(i + 1) % bs.length];
  else if (e.key === 'ArrowLeft' || e.key === 'ArrowUp') n = bs[(i - 1 + bs.length) % bs.length];
  else if (e.key === 'Home') n = bs[0];
  else if (e.key === 'End') n = bs[bs.length - 1];
  if (!n) return;
  e.preventDefault();
  bs.forEach((b) => { b.tabIndex = b === n ? 0 : -1; });
  n.focus();
});

// Juno starts typing the first time the window is actually on screen.
const io = new IntersectionObserver((en) => {
  if (en.some((x) => x.isIntersecting)) { io.disconnect(); ask(0); }
}, { threshold: 0.35 });
io.observe(log);

css:
.bkq-tabs {
  /* re-theme with these four */
  --bkq-tabs-paper: oklch(97.6% 0.004 100);
  --bkq-tabs-ink: oklch(16% 0.005 100);
  --bkq-tabs-hi: oklch(91% 0.19 108);
  --bkq-tabs-hot: oklch(60% 0.22 30);

  --bkq-tabs-muted: color-mix(in oklch, var(--bkq-tabs-ink) 66%, var(--bkq-tabs-paper));
  --bkq-tabs-hatch: repeating-linear-gradient(-45deg, color-mix(in oklch, var(--bkq-tabs-ink) 14%, transparent) 0 1.5px, transparent 1.5px 7px);
  --bkq-tabs-b: 3px solid var(--bkq-tabs-ink);
  --bkq-tabs-snap: cubic-bezier(.75, 0, .15, 1);
  --bkq-tabs-gutter: clamp(16px, 5cqi, 64px);
  --bkq-tabs-mono: ui-monospace, "SF Mono", Menlo, Consolas, monospace;

  container-type: inline-size;
  container-name: bkq-tabs;
  interpolate-size: allow-keywords;
  box-sizing: border-box;
  width: 100%;
  background: var(--bkq-tabs-paper);
  color: var(--bkq-tabs-ink);
  font: 500 15px/1.5 system-ui, -apple-system, "Segoe UI", Roboto, sans-serif;
  -webkit-font-smoothing: antialiased;

  & *, & *::before, & *::after { box-sizing: border-box; }
  & :where(h2, h3, p) { margin: 0; }
  & button { font: inherit; color: inherit; }
  & :focus-visible { outline: 3px solid var(--bkq-tabs-hot); outline-offset: 3px; }
}

.bkq-tabs-in {
  display: grid;
  gap: 28px;
  grid-template-columns: minmax(0, 1fr);
  grid-template-areas: "head" "nav" "panels";
  padding: clamp(32px, 5.5cqi, 72px) var(--bkq-tabs-gutter) clamp(40px, 6cqi, 84px);
  max-width: 1280px;
  margin-inline: auto;
}

/* ---- head ---- */
.bkq-tabs-head { grid-area: head; display: grid; gap: 14px; border-bottom: var(--bkq-tabs-b); padding-bottom: 18px; }
.bkq-tabs-brand {
  display: flex; flex-wrap: wrap; align-items: center; gap: 6px 12px;
  font: 600 11.5px/1.2 var(--bkq-tabs-mono); text-transform: uppercase; letter-spacing: .06em;
  & svg { width: 30px; height: 30px; fill: var(--bkq-tabs-hi); stroke: var(--bkq-tabs-ink); stroke-width: 2.2; stroke-linejoin: miter; }
  & b { font: 900 18px/1 system-ui, sans-serif; letter-spacing: -.02em; }
  & span { color: var(--bkq-tabs-muted); }
}
.bkq-tabs-title {
  font-size: clamp(44px, 10.5cqi, 148px);
  line-height: .84;
  font-weight: 900;
  letter-spacing: -.06em;
  text-transform: uppercase;
  text-wrap: balance;
  & span {
    display: block; width: fit-content; margin-top: 14px;
    padding: 4px 10px;
    font: 700 clamp(13px, 1.1cqi + 9px, 20px)/1.2 var(--bkq-tabs-mono);
    letter-spacing: 0; text-transform: uppercase;
    background: var(--bkq-tabs-hi);
    border: var(--bkq-tabs-b);
    rotate: -1.2deg;
  }
}
.bkq-tabs-meta {
  font: 600 12px/1.2 var(--bkq-tabs-mono); text-transform: uppercase; letter-spacing: .05em;
  color: var(--bkq-tabs-muted);
  font-variant-numeric: tabular-nums;
  & b { color: var(--bkq-tabs-ink); }
  & i { font-style: normal; color: var(--bkq-tabs-hot); padding-inline: 4px; }
}

/* ---- tabs ---- */
.bkq-tabs-nav { grid-area: nav; display: grid; gap: 20px; align-content: start; }
.bkq-tabs-list {
  position: relative;
  display: grid; grid-template-columns: repeat(2, minmax(0, 1fr));
  border: var(--bkq-tabs-b);
  box-shadow: 6px 6px 0 var(--bkq-tabs-ink);
  background: var(--bkq-tabs-paper);
}
.bkq-tabs-slab {
  position: absolute; z-index: 0; left: 0; top: 0;
  background: var(--bkq-tabs-hi);
  pointer-events: none;
}
.bkq-tabs-tab {
  position: relative; z-index: 1;
  display: grid;
  grid-template-columns: auto minmax(0, 1fr) auto;
  grid-template-areas: "no no ct" "lab lab lab";
  align-items: center;
  gap: 6px 10px;
  min-height: 76px;
  padding: 12px;
  border: 0; border-radius: 0;
  background: transparent;
  text-align: left;
  cursor: pointer;
  transition: background-color .12s;
  &:nth-child(odd of .bkq-tabs-tab) { border-right: var(--bkq-tabs-b); }
  &:nth-child(-n+3) { border-bottom: var(--bkq-tabs-b); }
  &:hover:not([aria-selected="true"]) { background: var(--bkq-tabs-hatch); }
  &:active .bkq-tabs-lab { translate: 2px 2px; }
  &:focus-visible { outline-offset: -7px; }
}
.bkq-tabs-no { grid-area: no; font: 800 12px/1 var(--bkq-tabs-mono); color: var(--bkq-tabs-hot); }
.bkq-tabs-lab { grid-area: lab; font: 900 clamp(16px, 1.2cqi + 12px, 22px)/1.05 system-ui, sans-serif; letter-spacing: -.03em; text-transform: uppercase; }
.bkq-tabs-ct {
  grid-area: ct;
  min-width: 26px; height: 26px; padding: 0 6px;
  display: grid; place-items: center;
  font: 800 12px/1 var(--bkq-tabs-mono); font-variant-numeric: tabular-nums;
  background: var(--bkq-tabs-ink); color: var(--bkq-tabs-paper);
  transition: background-color .12s, color .12s;
  .bkq-tabs-tab[aria-selected="true"] & { background: var(--bkq-tabs-paper); color: var(--bkq-tabs-ink); outline: 2px solid var(--bkq-tabs-ink); }
}
.bkq-tabs-call {
  font: 600 12.5px/1.55 var(--bkq-tabs-mono);
  padding: 12px 14px;
  border: var(--bkq-tabs-b); border-style: dashed;
  & b { text-transform: uppercase; background: var(--bkq-tabs-ink); color: var(--bkq-tabs-paper); padding: 1px 5px; margin-right: 4px; }
  & a { color: inherit; font-weight: 800; text-decoration: underline; text-decoration-thickness: 4px; text-decoration-color: var(--bkq-tabs-hi); text-underline-offset: 2px; text-decoration-skip-ink: none; white-space: nowrap; }
  & a:hover { text-decoration-color: var(--bkq-tabs-hot); }
}

/* ---- panels ---- */
.bkq-tabs-panels { grid-area: panels; min-width: 0; }
.bkq-tabs-panel {
  border: var(--bkq-tabs-b);
  box-shadow: 8px 8px 0 var(--bkq-tabs-ink);
  background: var(--bkq-tabs-paper);
  counter-reset: bkq-tabs-q;
  &[hidden] { display: none; }
}
.bkq-tabs-ph {
  display: flex; flex-wrap: wrap; align-items: baseline; justify-content: space-between; gap: 4px 16px;
  padding: 16px 18px;
  border-bottom: var(--bkq-tabs-b);
  background: var(--bkq-tabs-hatch);
  & h3 { font-size: clamp(26px, 2.4cqi + 14px, 40px); line-height: .95; font-weight: 900; letter-spacing: -.045em; text-transform: uppercase; }
  & p { font: 600 12px/1.4 var(--bkq-tabs-mono); text-transform: uppercase; letter-spacing: .03em; color: var(--bkq-tabs-muted); }
}
.bkq-tabs-q {
  counter-increment: bkq-tabs-q;
  & + & { border-top: var(--bkq-tabs-b); }
  & summary {
    list-style: none;
    display: grid; grid-template-columns: auto minmax(0, 1fr) 24px; align-items: center; gap: 14px;
    padding: 15px 18px;
    cursor: pointer;
    font-size: clamp(15px, .3cqi + 14px, 17px); font-weight: 750; letter-spacing: -.012em;
    transition: background-color .1s, color .1s;
    &::-webkit-details-marker { display: none; }
    &::before { content: "Q." counter(bkq-tabs-q, decimal-leading-zero); font: 800 11.5px/1 var(--bkq-tabs-mono); color: var(--bkq-tabs-hot); transition: color .1s; }
    &:hover { background: var(--bkq-tabs-hatch); }
    &:active span { translate: 2px 2px; }
    &:focus-visible { outline-offset: -6px; }
    & span { text-wrap: pretty; }
    & i {
      position: relative; width: 24px; height: 24px; border: 2.5px solid currentColor;
      &::before, &::after { content: ""; position: absolute; left: 50%; top: 50%; width: 11px; height: 2.5px; margin: -1.25px 0 0 -5.5px; background: currentColor; transition: rotate .22s var(--bkq-tabs-snap); }
      &::after { rotate: 90deg; }
    }
  }
  &[open] summary {
    background: var(--bkq-tabs-ink); color: var(--bkq-tabs-paper);
    &::before { color: var(--bkq-tabs-hi); }
    & i::after { rotate: 0deg; }
    & i { background: var(--bkq-tabs-hi); color: var(--bkq-tabs-ink); border-color: var(--bkq-tabs-hi); }
  }
  & p {
    padding: 16px 18px 18px calc(18px + 4.4ch);
    max-width: 70ch;
    font-size: 15px; line-height: 1.6; font-weight: 500;
    text-wrap: pretty;
    border-left: 10px solid var(--bkq-tabs-hi);
  }
}
@supports (interpolate-size: allow-keywords) {
  .bkq-tabs-q::details-content { block-size: 0; overflow: clip; transition: block-size .26s var(--bkq-tabs-snap), content-visibility .26s allow-discrete; }
  .bkq-tabs-q[open]::details-content { block-size: auto; }
}

@container bkq-tabs (min-width: 820px) {
  .bkq-tabs-in {
    grid-template-columns: minmax(250px, 3fr) minmax(0, 7fr);
    grid-template-areas: "head head" "nav panels";
    column-gap: clamp(28px, 4cqi, 56px);
  }
  .bkq-tabs-head { grid-template-columns: minmax(0, 1fr) auto; align-items: end; column-gap: 32px; }
  .bkq-tabs-brand { grid-column: 1 / -1; }
  .bkq-tabs-meta { text-align: right; }
  .bkq-tabs-list { grid-template-columns: minmax(0, 1fr); }
  .bkq-tabs-tab {
    grid-template-columns: 34px minmax(0, 1fr) auto;
    grid-template-areas: "no lab ct";
    min-height: 66px; padding: 12px 14px;
    &:nth-child(odd of .bkq-tabs-tab) { border-right: 0; }
    &:not(:last-child) { border-bottom: var(--bkq-tabs-b); }
  }
  .bkq-tabs-no { font-size: 13px; }
}

@media (prefers-reduced-motion: reduce) {
  .bkq-tabs-q::details-content { transition: none !important; }
  .bkq-tabs-q summary i::before, .bkq-tabs-q summary i::after { transition: none; }
}

