const reduce = matchMedia('(prefers-reduced-motion: reduce)');
const uid = Math.random().toString(36).slice(2, 7);
root.querySelectorAll('[id]').forEach((n) => { n.id += '-' + uid; });
['aria-controls', 'aria-labelledby'].forEach((a) => root.querySelectorAll('[' + a + ']').forEach((n) => n.setAttribute(a, n.getAttribute(a) + '-' + uid)));
if (root.hasAttribute('aria-labelledby')) root.setAttribute('aria-labelledby', root.getAttribute('aria-labelledby') + '-' + uid);

const list = root.querySelector('.bkq-tabs-list');
const slab = root.querySelector('.bkq-tabs-slab');
const tabs = [...root.querySelectorAll('.bkq-tabs-tab')];
const panelOf = (t) => root.querySelector('#' + t.getAttribute('aria-controls'));
const SNAP = 'cubic-bezier(.75, 0, .15, 1)';
let current = tabs.find((t) => t.getAttribute('aria-selected') === 'true') || tabs[0];

function geometry(t) {
  return { left: t.offsetLeft, top: t.offsetTop, width: t.offsetWidth, height: t.offsetHeight };
}
function placeSlab(animate) {
  const before = slab.getBoundingClientRect();
  const g = geometry(current);
  Object.assign(slab.style, { left: g.left + 'px', top: g.top + 'px', width: g.width + 'px', height: g.height + 'px' });
  if (!animate || reduce.matches || !before.width) return;
  // FLIP: start the slab where it was, let it snap to the new tab
  const after = slab.getBoundingClientRect();
  const dx = before.left - after.left, dy = before.top - after.top;
  const sx = before.width / after.width, sy = before.height / after.height;
  slab.animate([
    { transformOrigin: '0 0', transform: `translate(${dx}px, ${dy}px) scale(${sx}, ${sy})` },
    { transformOrigin: '0 0', transform: `translate(${dx * .08}px, ${dy * .08}px) scale(${1 + (sx - 1) * .08}, ${1 + (sy - 1) * .08})`, offset: .7 },
    { transformOrigin: '0 0', transform: 'none' },
  ], { duration: 340, easing: SNAP });
}

function select(t, focus) {
  if (t === current) { if (focus) t.focus(); return; }
  const old = current;
  current = t;
  tabs.forEach((x) => {
    const on = x === t;
    x.setAttribute('aria-selected', String(on));
    x.tabIndex = on ? 0 : -1;
  });
  panelOf(old).hidden = true;
  const p = panelOf(t);
  p.hidden = false;
  placeSlab(true);
  if (focus) t.focus();
  if (reduce.matches) return;
  p.animate([{ clipPath: 'inset(0 0 100% 0)' }, { clipPath: 'inset(0 0 0% 0)' }], { duration: 360, easing: SNAP });
  p.querySelectorAll('.bkq-tabs-q').forEach((q, i) => {
    q.animate([{ opacity: 0, transform: 'translateX(-14px)' }, { opacity: 1, transform: 'none' }],
      { duration: 260, delay: 120 + i * 45, easing: SNAP, fill: 'backwards' });
  });
}

tabs.forEach((t) => t.addEventListener('click', () => select(t, false)));
list.addEventListener('keydown', (e) => {
  const i = tabs.indexOf(e.target);
  if (i < 0) return;
  let n = null;
  if (e.key === 'ArrowRight' || e.key === 'ArrowDown') n = tabs[(i + 1) % tabs.length];
  else if (e.key === 'ArrowLeft' || e.key === 'ArrowUp') n = tabs[(i - 1 + tabs.length) % tabs.length];
  else if (e.key === 'Home') n = tabs[0];
  else if (e.key === 'End') n = tabs[tabs.length - 1];
  if (!n) return;
  e.preventDefault();
  select(n, true);
});

// Escape closes the open question you are in.
root.addEventListener('keydown', (e) => {
  if (e.key !== 'Escape') return;
  const d = e.target.closest && e.target.closest('.bkq-tabs-q[open]');
  if (d) { d.open = false; d.querySelector('summary').focus(); }
});

// Keep the slab glued to its tab when the grid reflows, and report the real orientation.
const ro = new ResizeObserver(() => {
  if (!root.isConnected) { ro.disconnect(); return; }
  placeSlab(false);
  const vertical = getComputedStyle(list).gridTemplateColumns.trim().split(/\s+/).length === 1;
  list.setAttribute('aria-orientation', vertical ? 'vertical' : 'horizontal');
});
ro.observe(list);
placeSlab(false);

