.bkq-offices {
  /* re-theme with these four */
  --bkq-offices-bg: oklch(15.5% 0.008 60);
  --bkq-offices-ink: oklch(93% 0.018 85);
  --bkq-offices-gold: oklch(80% 0.085 82);
  --bkq-offices-open: oklch(80% 0.12 150);

  --bkq-offices-muted: color-mix(in oklch, var(--bkq-offices-ink) 60%, var(--bkq-offices-bg));
  --bkq-offices-faint: color-mix(in oklch, var(--bkq-offices-ink) 32%, var(--bkq-offices-bg));
  --bkq-offices-line: color-mix(in oklch, var(--bkq-offices-gold) 18%, var(--bkq-offices-bg));
  --bkq-offices-lift: color-mix(in oklch, var(--bkq-offices-gold) 7%, var(--bkq-offices-bg));
  --bkq-offices-serif: ui-serif, "Iowan Old Style", "Palatino Linotype", Palatino, Georgia, serif;
  --bkq-offices-mono: ui-monospace, Menlo, Consolas, monospace;
  --bkq-offices-out: cubic-bezier(.19, 1, .22, 1);
  --bkq-offices-silk: cubic-bezier(.65, .05, .36, 1);
  --bkq-offices-gutter: clamp(16px, 5cqi, 72px);

  container-type: inline-size;
  container-name: bkq-offices;
  box-sizing: border-box;
  width: 100%;
  background: var(--bkq-offices-bg);
  color: var(--bkq-offices-ink);
  font: 400 15px/1.55 system-ui, -apple-system, "Segoe UI", Roboto, sans-serif;
  -webkit-font-smoothing: antialiased;

  & *, & *::before, & *::after { box-sizing: border-box; }
  & :where(h2, h3, p, ul) { margin: 0; padding: 0; }
  & button { font: inherit; color: inherit; }
  & :focus-visible { outline: 1.5px solid var(--bkq-offices-gold); outline-offset: 4px; }
}

.bkq-offices-in {
  display: grid;
  gap: 24px;
  grid-template-columns: minmax(0, 1fr);
  grid-template-areas: "head" "atlas" "list";
  padding: clamp(40px, 6cqi, 80px) var(--bkq-offices-gutter);
  max-width: 1320px;
  margin-inline: auto;
}

.bkq-offices-head { grid-area: head; display: grid; gap: 14px; }
.bkq-offices-brand {
  display: flex; flex-wrap: wrap; align-items: center; gap: 6px 12px;
  font: 500 10.5px/1.2 var(--bkq-offices-mono); letter-spacing: .22em; text-transform: uppercase; color: var(--bkq-offices-muted);
  & svg { width: 26px; height: 26px; fill: none; stroke: var(--bkq-offices-gold); stroke-width: 1.1; }
  & b { font: 400 21px/1 var(--bkq-offices-serif); letter-spacing: .32em; text-transform: uppercase; color: var(--bkq-offices-ink); }
}
.bkq-offices-title {
  font: 400 clamp(32px, 3.8cqi + 16px, 62px)/1.02 var(--bkq-offices-serif);
  letter-spacing: -.02em;
  text-wrap: balance;
  max-width: 16ch;
}
.bkq-offices-lede { max-width: 50ch; color: var(--bkq-offices-muted); text-wrap: pretty; font-size: clamp(14.5px, .35cqi + 13.5px, 16.5px); }

/* ---- atlas ---- */
.bkq-offices-atlas { grid-area: atlas; position: relative; display: grid; gap: 12px; }
.bkq-offices-map {
  position: relative;
  aspect-ratio: 2.4;
  border: 1px solid var(--bkq-offices-line);
  border-radius: 4px;
  overflow: hidden;
  background: radial-gradient(120% 90% at 50% 50%, color-mix(in oklch, var(--bkq-offices-gold) 5%, transparent), transparent 70%);
}
.bkq-offices-cv { position: absolute; inset: 0; width: 100%; height: 100%; display: block; }
.bkq-offices-pins { position: absolute; inset: 0; pointer-events: none; }
.bkq-offices-pin {
  position: absolute; width: 0; height: 0;
  &::before {
    content: ""; position: absolute; left: -4px; top: -4px; width: 8px; height: 8px;
    background: var(--bkq-offices-gold); rotate: 45deg;
    box-shadow: 0 0 0 3px color-mix(in oklch, var(--bkq-offices-bg) 70%, transparent);
    transition: scale .5s var(--bkq-offices-out), background-color .3s;
  }
  &::after {
    content: ""; position: absolute; left: -16px; top: -16px; width: 32px; height: 32px; border-radius: 50%;
    border: 1px solid var(--bkq-offices-gold);
    opacity: 0; scale: .3;
    transition: opacity .4s, scale .7s var(--bkq-offices-out);
  }
  & span {
    position: absolute; left: 12px; top: -10px;
    padding: 2px 8px;
    white-space: nowrap;
    font: 500 11px/1.4 var(--bkq-offices-mono); letter-spacing: .06em;
    background: color-mix(in oklch, var(--bkq-offices-bg) 82%, transparent);
    border: 1px solid var(--bkq-offices-line);
    color: var(--bkq-offices-ink);
    font-variant-numeric: tabular-nums;
    opacity: 0; translate: -6px 0;
    transition: opacity .35s var(--bkq-offices-out), translate .5s var(--bkq-offices-out);
  }
  &[data-flip] span { left: auto; right: 12px; translate: 6px 0; }
  &[data-hot] {
    &::before { scale: 1.5; background: var(--bkq-offices-ink); }
    &::after { opacity: .9; scale: 1; animation: bkq-offices-ping 2.4s var(--bkq-offices-out) infinite .7s; }
    & span { opacity: 1; translate: 0 0; }
  }
}
@keyframes bkq-offices-ping { 0% { scale: 1; opacity: .9; } 70%, 100% { scale: 1.9; opacity: 0; } }
.bkq-offices-key {
  position: absolute; right: 12px; bottom: 10px;
  display: flex; align-items: center; gap: 10px;
  font: 500 10px/1 var(--bkq-offices-mono); letter-spacing: .14em; text-transform: uppercase;
  color: var(--bkq-offices-muted);
  font-variant-numeric: tabular-nums;
}
.bkq-offices-sun {
  width: 40px; height: 6px; border-radius: 3px;
  background: linear-gradient(90deg, color-mix(in oklch, var(--bkq-offices-gold) 18%, var(--bkq-offices-bg)), var(--bkq-offices-gold));
}

/* ---- the selected salon ---- */
.bkq-offices-card {
  padding: 18px 20px;
  border: 1px solid var(--bkq-offices-line);
  border-radius: 4px;
  background: color-mix(in oklch, var(--bkq-offices-bg) 88%, var(--bkq-offices-gold));
  & > div { display: grid; gap: 6px; justify-items: start; }
  & > div > * {
    transition: opacity .6s var(--bkq-offices-out), translate .8s var(--bkq-offices-out);
    transition-delay: calc(var(--i, 0) * 60ms);
    @starting-style { opacity: 0; translate: 0 8px; }
  }
  & h3 { margin: 0; font: italic 400 24px/1.1 var(--bkq-offices-serif); color: var(--bkq-offices-gold); }
  & p { font-size: 13.5px; line-height: 1.45; color: var(--bkq-offices-muted); }
  & .bkq-offices-when { font: 500 10.5px/1.6 var(--bkq-offices-mono); letter-spacing: .06em; color: var(--bkq-offices-ink); }
  & .bkq-offices-geo { font: 500 9.5px/1.5 var(--bkq-offices-mono); letter-spacing: .08em; color: var(--bkq-offices-faint); white-space: pre-line; }
  & a {
    margin-top: 6px;
    font: 500 11px/1 var(--bkq-offices-mono); letter-spacing: .2em; text-transform: uppercase;
    color: var(--bkq-offices-gold); text-decoration: none;
    padding-bottom: 5px;
    background: linear-gradient(currentColor, currentColor) 0 100% / 30% 1px no-repeat;
    transition: background-size .5s var(--bkq-offices-out);
    &:hover { background-size: 100% 1px; }
  }
}

/* ---- salons strip ---- */
.bkq-offices-list {
  grid-area: list;
  display: grid; grid-template-columns: repeat(2, minmax(0, 1fr));
  border-top: 1px solid var(--bkq-offices-line);
}
.bkq-offices-btn {
  position: relative;
  display: grid;
  grid-template-columns: minmax(0, 1fr) auto;
  grid-template-areas: "city city" "cty cty" "clock clock" "st st";
  align-content: start;
  gap: 0 10px;
  padding: 14px 12px 16px;
  border: 0; border-bottom: 1px solid var(--bkq-offices-line);
  background: none; cursor: pointer; text-align: left;
  transition: background-color .3s;
  &:nth-child(odd) { border-right: 1px solid var(--bkq-offices-line); }
  &::before {
    content: ""; position: absolute; left: -1px; right: 0; top: -1px; height: 2px;
    background: var(--bkq-offices-gold);
    scale: 0 1; transform-origin: 0 50%;
    transition: scale .7s var(--bkq-offices-out);
  }
  &[aria-selected="true"]::before { scale: 1 1; }
  &:hover { background: var(--bkq-offices-lift); }
  &:focus-visible { outline-offset: -3px; }
}
.bkq-offices-city { grid-area: city; font: 400 clamp(18px, .5cqi + 15px, 22px)/1.2 var(--bkq-offices-serif); letter-spacing: -.01em; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; transition: color .3s; }
.bkq-offices-btn[aria-selected="true"] .bkq-offices-city { color: var(--bkq-offices-gold); font-style: italic; }
.bkq-offices-cty { grid-area: cty; font: 500 9.5px/1.8 var(--bkq-offices-mono); letter-spacing: .2em; text-transform: uppercase; color: var(--bkq-offices-faint); white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
.bkq-offices-clock { grid-area: clock; margin-top: 10px; font: 300 26px/1.1 var(--bkq-offices-mono); letter-spacing: -.04em; font-variant-numeric: tabular-nums; }
.bkq-offices-st {
  grid-area: st;
  display: inline-flex; align-items: center; gap: 6px;
  font: 500 10px/1.8 var(--bkq-offices-mono); letter-spacing: .04em; color: var(--bkq-offices-muted); white-space: nowrap; overflow: hidden; text-overflow: ellipsis;
  &::before { content: ""; width: 6px; height: 6px; flex: none; border-radius: 50%; border: 1px solid var(--bkq-offices-faint); }
  &[data-open]::before { background: var(--bkq-offices-open); border-color: var(--bkq-offices-open); box-shadow: 0 0 8px var(--bkq-offices-open); }
  &[data-open] { color: var(--bkq-offices-ink); }
}

@container bkq-offices (min-width: 620px) {
  .bkq-offices-list { grid-template-columns: repeat(3, minmax(0, 1fr)); }
  .bkq-offices-btn:nth-child(odd) { border-right: 0; }
  .bkq-offices-btn:not(:nth-child(3n)) { border-right: 1px solid var(--bkq-offices-line); }
  .bkq-offices-map { aspect-ratio: 2.69; }
  .bkq-offices-atlas { display: block; }
  .bkq-offices-card { position: absolute; left: 12px; bottom: 12px; width: min(250px, 30%); padding: 14px 16px; background: color-mix(in oklch, var(--bkq-offices-bg) 86%, transparent); backdrop-filter: blur(6px); }
}
@container bkq-offices (min-width: 980px) {
  .bkq-offices-head { grid-template-columns: minmax(0, 1.3fr) minmax(0, 1fr); align-items: end; column-gap: 56px; }
  .bkq-offices-brand { grid-column: 1 / -1; }
  .bkq-offices-list { grid-template-columns: repeat(6, minmax(0, 1fr)); }
  .bkq-offices-btn { border-bottom: 0; }
  .bkq-offices-btn:not(:nth-child(3n)) { border-right: 0; }
  .bkq-offices-btn:not(:last-child) { border-right: 1px solid var(--bkq-offices-line); }
}

@media (prefers-reduced-motion: reduce) {
  .bkq-offices-card > div > *, .bkq-offices-btn::before, .bkq-offices-city, .bkq-offices-pin::before, .bkq-offices-pin::after, .bkq-offices-pin span { transition: none; }
  .bkq-offices-pin[data-hot]::after { animation: none; }
}

@property --bkq-booking-total { syntax: "<integer>"; inherits: true; initial-value: 0; }

.bkq-booking {
  /* re-theme with these four */
  --bkq-booking-bg: oklch(94.5% 0.008 80);
  --bkq-booking-ink: oklch(22% 0.012 260);
  --bkq-booking-accent: oklch(66% 0.19 45);
  --bkq-booking-card: oklch(98.6% 0.004 80);

  --bkq-booking-muted: color-mix(in oklch, var(--bkq-booking-ink) 62%, var(--bkq-booking-bg));
  --bkq-booking-faint: color-mix(in oklch, var(--bkq-booking-ink) 36%, var(--bkq-booking-bg));
  --bkq-booking-line: color-mix(in oklch, var(--bkq-booking-ink) 14%, var(--bkq-booking-bg));
  --bkq-booking-soft: color-mix(in oklch, var(--bkq-booking-accent) 12%, var(--bkq-booking-card));
  --bkq-booking-mono: ui-monospace, "SF Mono", Menlo, Consolas, monospace;
  --bkq-booking-out: cubic-bezier(.2, .85, .25, 1);
  --bkq-booking-spring: linear(0, .009, .035 2.1%, .141 4.4%, .723 12.9%, .938 16.7%, 1.017 19.4%, 1.067 22.4%, 1.084 25.1%, 1.077 28.8%, 1.038 34.4%, 1.006 40.6%, .99 47.7%, .995 63.1%, 1);
  --bkq-booking-gutter: clamp(16px, 5cqi, 64px);

  container-type: inline-size;
  container-name: bkq-booking;
  box-sizing: border-box;
  width: 100%;
  background: var(--bkq-booking-bg);
  color: var(--bkq-booking-ink);
  font: 400 15px/1.5 system-ui, -apple-system, "Segoe UI", Roboto, sans-serif;
  -webkit-font-smoothing: antialiased;
  accent-color: var(--bkq-booking-accent);

  & *, & *::before, & *::after { box-sizing: border-box; }
  & :where(h2, p, fieldset, legend) { margin: 0; padding: 0; }
  & fieldset { border: 0; min-width: 0; }
  & :where(button, input) { font: inherit; color: inherit; }
  & :focus-visible { outline: 2px solid var(--bkq-booking-accent); outline-offset: 2px; border-radius: 6px; }
}

.bkq-booking-in {
  display: grid;
  gap: 26px;
  grid-template-columns: minmax(0, 1fr);
  grid-template-areas: "head" "services" "plan";
  padding: clamp(36px, 6cqi, 80px) var(--bkq-booking-gutter);
  max-width: 1280px;
  margin-inline: auto;
}

.bkq-booking-head { grid-area: head; display: grid; gap: 12px; align-content: start; }
.bkq-booking-brand {
  display: flex; flex-wrap: wrap; align-items: center; gap: 4px 10px;
  font: 500 11px/1.2 var(--bkq-booking-mono); letter-spacing: .06em; text-transform: uppercase; color: var(--bkq-booking-muted);
  & svg { width: 26px; height: 26px; fill: none; stroke: var(--bkq-booking-accent); stroke-width: 1.7; stroke-linecap: round; }
  & b { font: 750 17px/1 system-ui, sans-serif; letter-spacing: -.02em; text-transform: none; color: var(--bkq-booking-ink); }
}
.bkq-booking-title { font-size: clamp(32px, 3.6cqi + 16px, 54px); line-height: 1; letter-spacing: -.04em; font-weight: 760; text-wrap: balance; }
.bkq-booking-lede { max-width: 42ch; color: var(--bkq-booking-muted); text-wrap: pretty; }

.bkq-booking :is(.bkq-booking-services, .bkq-booking-days) > legend, .bkq-booking-boardh > span {
  display: flex; align-items: baseline; gap: 8px;
  margin-bottom: 10px;
  font: 650 11px/1.3 var(--bkq-booking-mono); letter-spacing: .1em; text-transform: uppercase;
  & span { color: var(--bkq-booking-accent); }
}

/* ---- services ---- */
.bkq-booking-services { grid-area: services; display: grid; grid-template-columns: repeat(2, minmax(0, 1fr)); gap: 8px; align-content: start; & > legend { grid-column: 1 / -1; } }
.bkq-booking-svc {
  position: relative;
  display: grid;
  grid-template-columns: minmax(0, 1fr) auto;
  grid-template-areas: "n p" "d d" "t t";
  grid-template-rows: auto auto 1fr;
  gap: 2px 12px;
  padding: 13px 16px 13px 18px;
  border-radius: 12px;
  background: var(--bkq-booking-card);
  border: 1.5px solid var(--bkq-booking-line);
  cursor: pointer;
  transition: border-color .2s, box-shadow .3s var(--bkq-booking-out), translate .45s var(--bkq-booking-spring);
  & input { position: absolute; opacity: 0; inset: 0; margin: 0; cursor: pointer; }
  &::before {
    content: ""; position: absolute; left: -1.5px; top: 12px; bottom: 12px; width: 4px; border-radius: 0 3px 3px 0;
    background: var(--bkq-booking-accent);
    scale: 1 0; transition: scale .4s var(--bkq-booking-spring);
  }
  &:hover { border-color: color-mix(in oklch, var(--bkq-booking-ink) 30%, var(--bkq-booking-bg)); }
  &:has(:checked) { border-color: var(--bkq-booking-ink); box-shadow: 0 10px 24px -16px color-mix(in oklch, var(--bkq-booking-ink) 60%, transparent); &::before { scale: 1 1; } }
  &:has(:focus-visible) { outline: 2px solid var(--bkq-booking-accent); outline-offset: 2px; }
}
.bkq-booking-svcn { grid-area: n; font-weight: 680; letter-spacing: -.01em; }
.bkq-booking-svcd { grid-area: d; display: none; font-size: 13px; color: var(--bkq-booking-muted); text-wrap: pretty; }
.bkq-booking-svct {
  grid-area: t; justify-self: start; align-self: end; margin-top: 6px;
  font: 600 11px/1 var(--bkq-booking-mono); padding: 4px 7px; border-radius: 5px;
  background: var(--bkq-booking-line); font-variant-numeric: tabular-nums;
  .bkq-booking-svc:has(:checked) & { background: var(--bkq-booking-ink); color: var(--bkq-booking-card); }
}
.bkq-booking-svcp { grid-area: p; font: 650 15px/1.3 var(--bkq-booking-mono); font-variant-numeric: tabular-nums; }

/* ---- plan ---- */
.bkq-booking-plan { grid-area: plan; display: grid; gap: 22px; min-width: 0; align-content: start; }
.bkq-booking-dayrow {
  display: grid; grid-auto-flow: column; grid-auto-columns: minmax(64px, 1fr); gap: 6px;
  overflow-x: auto; scrollbar-width: none; scroll-snap-type: x mandatory;
  &::-webkit-scrollbar { display: none; }
}
.bkq-booking-day {
  position: relative; scroll-snap-align: start;
  display: grid; justify-items: center; gap: 2px;
  padding: 10px 6px;
  border-radius: 12px;
  border: 1.5px solid var(--bkq-booking-line);
  background: var(--bkq-booking-card);
  cursor: pointer;
  transition: background-color .2s, border-color .2s, color .2s;
  & input { position: absolute; inset: 0; opacity: 0; margin: 0; cursor: pointer; }
  & small { font: 600 10.5px/1 var(--bkq-booking-mono); letter-spacing: .1em; text-transform: uppercase; color: var(--bkq-booking-muted); }
  & b { font: 700 22px/1.1 system-ui, sans-serif; letter-spacing: -.03em; font-variant-numeric: tabular-nums; }
  & i { font: 500 10px/1 var(--bkq-booking-mono); font-style: normal; color: var(--bkq-booking-faint); font-variant-numeric: tabular-nums; }
  &:hover { border-color: color-mix(in oklch, var(--bkq-booking-ink) 30%, var(--bkq-booking-bg)); }
  &:has(:checked) { background: var(--bkq-booking-ink); border-color: var(--bkq-booking-ink); color: var(--bkq-booking-card); & small, & i { color: color-mix(in oklch, var(--bkq-booking-card) 70%, var(--bkq-booking-ink)); } }
  &:has(:focus-visible) { outline: 2px solid var(--bkq-booking-accent); outline-offset: 2px; }
  &[data-full] b { text-decoration: line-through; text-decoration-thickness: 2px; opacity: .55; }
}

.bkq-booking-board { display: grid; gap: 8px; }
.bkq-booking-boardh { display: flex; justify-content: space-between; align-items: baseline; gap: 12px; & > span { margin-bottom: 0; } }
.bkq-booking-fit { font: 600 11.5px/1 var(--bkq-booking-mono); color: var(--bkq-booking-muted); font-variant-numeric: tabular-nums; white-space: nowrap; }
.bkq-booking-track {
  container-type: inline-size;
  container-name: bkq-booking-track;
  position: relative; height: 52px;
  border-radius: 10px;
  background:
    repeating-linear-gradient(90deg, var(--bkq-booking-line) 0 1px, transparent 1px calc(100% / 20)),
    var(--bkq-booking-card);
  border: 1.5px solid var(--bkq-booking-line);
  overflow: hidden;
}
.bkq-booking-job {
  position: absolute; top: 6px; bottom: 6px;
  left: calc(var(--s) / 600 * 100%); width: calc(var(--d) / 600 * 100%);
  border-radius: 6px;
  background: repeating-linear-gradient(-45deg, color-mix(in oklch, var(--bkq-booking-ink) 22%, transparent) 0 2px, transparent 2px 6px), color-mix(in oklch, var(--bkq-booking-ink) 9%, var(--bkq-booking-card));
  border: 1px solid color-mix(in oklch, var(--bkq-booking-ink) 28%, var(--bkq-booking-bg));
  display: grid; place-items: center; overflow: hidden;
  font: 600 9.5px/1 var(--bkq-booking-mono); letter-spacing: .06em; text-transform: uppercase; color: var(--bkq-booking-muted);
  transition: opacity .35s var(--bkq-booking-out), translate .5s var(--bkq-booking-spring);
  transition-delay: calc(var(--i, 0) * 40ms);
  @starting-style { opacity: 0; translate: 0 6px; }
  &[data-lunch] { background: color-mix(in oklch, var(--bkq-booking-ink) 5%, var(--bkq-booking-card)); border-style: dashed; }
}
.bkq-booking-ghost, .bkq-booking-pick {
  position: absolute; inset: 4px 0;
  pointer-events: none;
  clip-path: inset(0 100% 0 0 round 7px);
  transition: clip-path .42s var(--bkq-booking-spring), opacity .25s;
  & i { position: absolute; inset: 0; border-radius: 7px; }
}
.bkq-booking-ghost {
  opacity: 0;
  & i { background: repeating-linear-gradient(-45deg, color-mix(in oklch, var(--bkq-booking-accent) 55%, transparent) 0 2px, color-mix(in oklch, var(--bkq-booking-accent) 16%, transparent) 2px 7px); }
  &[data-on] { opacity: 1; }
}
.bkq-booking-pick {
  opacity: 0;
  & i { background: var(--bkq-booking-accent); box-shadow: inset 0 0 0 1.5px color-mix(in oklch, var(--bkq-booking-accent) 70%, var(--bkq-booking-ink)); }
  &[data-on] { opacity: 1; }
}
.bkq-booking-ruler {
  display: flex; justify-content: space-between;
  font: 500 10.5px/1 var(--bkq-booking-mono); color: var(--bkq-booking-faint); font-variant-numeric: tabular-nums;
  & span { width: 0; display: flex; justify-content: center; }
  & span:first-child { justify-content: flex-start; } & span:last-child { justify-content: flex-end; }
}

.bkq-booking-slots { display: flex; flex-wrap: wrap; gap: 6px; margin-top: 6px; min-height: 40px; }
.bkq-booking-slot {
  position: relative;
  display: grid; place-items: center;
  min-width: 70px; height: 40px; padding: 0 10px;
  border-radius: 9px;
  border: 1.5px solid var(--bkq-booking-line);
  background: var(--bkq-booking-card);
  font: 600 13.5px/1 var(--bkq-booking-mono); font-variant-numeric: tabular-nums;
  cursor: pointer;
  transition: background-color .15s, border-color .15s, color .15s;
  & input { position: absolute; inset: 0; opacity: 0; margin: 0; cursor: pointer; }
  &:hover { border-color: var(--bkq-booking-accent); }
  &:has(:checked) { background: var(--bkq-booking-accent); border-color: var(--bkq-booking-accent); color: var(--bkq-booking-card); }
  &:has(:focus-visible) { outline: 2px solid var(--bkq-booking-ink); outline-offset: 2px; }
}
.bkq-booking-none { font-size: 13.5px; color: var(--bkq-booking-muted); padding: 10px 0; &[hidden] { display: none; } }
.bkq-booking-sr { position: absolute; width: 1px; height: 1px; overflow: hidden; clip-path: inset(50%); white-space: nowrap; }

/* ---- summary ---- */
.bkq-booking-sum {
  position: relative;
  display: grid; grid-template-columns: minmax(0, 1fr) auto; grid-template-areas: "lines lines" "total go";
  gap: 14px 16px; align-items: end;
  padding: 18px;
  border-radius: 16px;
  background: var(--bkq-booking-card);
  border: 1.5px solid var(--bkq-booking-ink);
  box-shadow: 0 18px 40px -28px color-mix(in oklch, var(--bkq-booking-ink) 70%, transparent);
}
.bkq-booking-lines {
  grid-area: lines; display: grid; gap: 8px;
  padding-bottom: 14px; border-bottom: 1.5px dashed var(--bkq-booking-line);
  & p { display: flex; justify-content: space-between; gap: 12px; font-weight: 600; }
  & b { font: 650 14px/1.4 var(--bkq-booking-mono); font-variant-numeric: tabular-nums; white-space: nowrap; }
}
.bkq-booking-addon {
  display: flex; align-items: center; gap: 10px; cursor: pointer; font-size: 14px; color: var(--bkq-booking-muted);
  & input { width: 18px; height: 18px; margin: 0; flex: none; }
  & b { margin-left: auto; color: var(--bkq-booking-faint); transition: color .2s; }
  &:has(:checked) { color: var(--bkq-booking-ink); & b { color: var(--bkq-booking-ink); } }
}
.bkq-booking-when { font: 600 12px/1.4 var(--bkq-booking-mono) !important; color: var(--bkq-booking-muted); font-variant-numeric: tabular-nums; &[data-set] { color: var(--bkq-booking-accent); } }
.bkq-booking-total {
  grid-area: total; display: grid;
  & span { font: 600 10.5px/1 var(--bkq-booking-mono); letter-spacing: .1em; text-transform: uppercase; color: var(--bkq-booking-muted); }
  & b {
    font: 760 clamp(30px, 2cqi + 20px, 40px)/1.1 system-ui, sans-serif; letter-spacing: -.04em; font-variant-numeric: tabular-nums;
    transition: --bkq-booking-total .7s var(--bkq-booking-out);
    counter-reset: bkq-booking-t var(--bkq-booking-total);
    &::before { content: "£" counter(bkq-booking-t); }
  }
}
.bkq-booking-go {
  grid-area: go;
  height: 50px; padding: 0 22px;
  border: 0; border-radius: 12px;
  background: var(--bkq-booking-accent); color: var(--bkq-booking-card);
  font-size: 15px; font-weight: 700; letter-spacing: -.01em;
  cursor: pointer;
  transition: background-color .2s, opacity .2s, translate .4s var(--bkq-booking-spring);
  &:hover:not(:disabled) { background: color-mix(in oklch, var(--bkq-booking-accent) 86%, var(--bkq-booking-ink)); translate: 0 -2px; }
  &:disabled { opacity: .4; cursor: not-allowed; }
}
.bkq-booking-ok {
  position: absolute; inset: 0; z-index: 2;
  display: grid; grid-template-columns: auto minmax(0, 1fr); align-content: center; gap: 10px 14px;
  padding: 18px 20px;
  border-radius: 15px;
  background: var(--bkq-booking-ink); color: var(--bkq-booking-card);
  clip-path: circle(150% at 85% 85%);
  transition: clip-path .7s var(--bkq-booking-out), display .7s allow-discrete;
  @starting-style { clip-path: circle(0% at 85% 85%); }
  &[hidden] { display: none; clip-path: circle(0% at 85% 85%); }
  & svg { width: 34px; height: 34px; fill: none; stroke: var(--bkq-booking-accent); stroke-width: 1.8; stroke-linecap: round; stroke-linejoin: round; }
  & p { align-self: center; text-wrap: pretty; font-size: 14.5px; }
  & b { color: var(--bkq-booking-accent); }
  &:focus-visible { outline-offset: 3px; }
}
.bkq-booking-again {
  grid-column: 2; justify-self: start;
  padding: 0 0 2px; border: 0; border-bottom: 1.5px solid currentColor; background: none; cursor: pointer;
  font-size: 13.5px; font-weight: 650; color: var(--bkq-booking-card);
}

@container bkq-booking-track (max-width: 520px) {
  .bkq-booking-job { font-size: 0; }
}
@container bkq-booking (min-width: 560px) {
  .bkq-booking-svcd { display: block; }
}
@container bkq-booking (min-width: 900px) {
  .bkq-booking-in {
    grid-template-columns: minmax(0, 5fr) minmax(0, 7fr);
    grid-template-rows: auto 1fr;
    grid-template-areas: "head plan" "services plan";
    column-gap: clamp(36px, 5cqi, 80px);
  }
  .bkq-booking-services { grid-template-columns: minmax(0, 1fr); }
}

@media (prefers-reduced-motion: reduce) {
  .bkq-booking-ghost, .bkq-booking-pick, .bkq-booking-job, .bkq-booking-ok, .bkq-booking-svc, .bkq-booking-go { transition-duration: .01s; transition-delay: 0s; }
  .bkq-booking-total b { transition: none; }
}

