const doc = root.ownerDocument;
const reduce = matchMedia('(prefers-reduced-motion: reduce)');
const uid = Math.random().toString(36).slice(2, 7);
root.querySelectorAll('[id]').forEach((n) => { n.id += '-' + uid; });
if (root.hasAttribute('aria-labelledby')) root.setAttribute('aria-labelledby', root.getAttribute('aria-labelledby') + '-' + uid);
const SPRING = 'linear(0, .009, .035 2.1%, .141 4.4%, .723 12.9%, .938 16.7%, 1.017 19.4%, 1.067 22.4%, 1.084 25.1%, 1.077 28.8%, 1.038 34.4%, 1.006 40.6%, .99 47.7%, .995 63.1%, 1)';
const DAY = 600;                       // 08:00 to 18:00, in minutes
const LUNCH = [270, 30];               // 12:30, half an hour with the stand closed
// jobs already on the stand, [start, length] in minutes after 08:00; a day uses one of these by date
const PATTERNS = [
  [[0, 90], [120, 45], [360, 120]],
  [[30, 60], [180, 90], [420, 60], [510, 90]],
  [[0, 120], [330, 45], [450, 30]],
  [[60, 90], [300, 60], [390, 120]],
  [[0, 45], [90, 120], [330, 90], [480, 60]],
  [[150, 60], [360, 45], [450, 150]],
];

const svcInputs = [...root.querySelectorAll('.bkq-booking-svc input')];
svcInputs.forEach((i) => { i.name = 'bkq-booking-svc-' + uid; });
const dayRow = root.querySelector('.bkq-booking-dayrow');
const jobsEl = root.querySelector('.bkq-booking-jobs');
const ghost = root.querySelector('.bkq-booking-ghost');
const pick = root.querySelector('.bkq-booking-pick');
const slotsEl = root.querySelector('.bkq-booking-slots');
const none = root.querySelector('.bkq-booking-none');
const fitEl = root.querySelector('.bkq-booking-fit');
const what = root.querySelector('.bkq-booking-what');
const wp = root.querySelector('.bkq-booking-wp');
const when = root.querySelector('.bkq-booking-when');
const loan = root.querySelector('.bkq-booking-loan');
const tot = root.querySelector('.bkq-booking-tot');
const go = root.querySelector('.bkq-booking-go');
const ok = root.querySelector('.bkq-booking-ok');

const hm = (m) => { const t = 480 + m; return String(Math.floor(t / 60)).padStart(2, '0') + ':' + String(t % 60).padStart(2, '0'); };
const fmt = (d, o) => new Intl.DateTimeFormat('en-GB', o).format(d);

// the next six days the workshop is open: Tuesday to Saturday
const days = [];
for (const d = new Date(); days.length < 6;) {
  d.setDate(d.getDate() + 1);
  if (d.getDay() >= 2) days.push({ date: new Date(d), jobs: [LUNCH, ...PATTERNS[d.getDate() % 6]].sort((a, b) => a[0] - b[0]) });
}

const state = { svc: svcInputs.find((i) => i.checked) || svcInputs[2], day: 0, start: null };
const dur = () => +state.svc.dataset.min;
const fits = (jobs, d) => {
  const out = [];
  for (let s = 0; s + d <= DAY; s += 30) if (!jobs.some(([a, l]) => s < a + l && a < s + d)) out.push(s);
  return out;
};

// ---- days ----
const dayInputs = days.map((d, i) => {
  const lab = doc.createElement('label');
  lab.className = 'bkq-booking-day';
  lab.innerHTML = '<input type="radio"><small></small><b></b><i></i>';
  const inp = lab.querySelector('input');
  inp.name = 'bkq-booking-day-' + uid; inp.value = i; inp.checked = i === 0;
  inp.setAttribute('aria-label', fmt(d.date, { weekday: 'long', day: 'numeric', month: 'long' }));
  lab.querySelector('small').textContent = fmt(d.date, { weekday: 'short' });
  lab.querySelector('b').textContent = d.date.getDate();
  dayRow.append(lab);
  inp.addEventListener('change', () => { state.day = i; update(true); });
  return { lab, inp, free: lab.querySelector('i') };
});

// ---- the stand ----
function clip(el, s, d) { el.style.clipPath = `inset(0 ${(100 - (s + d) / DAY * 100).toFixed(3)}% 0 ${(s / DAY * 100).toFixed(3)}% round 7px)`; }
function drawJobs() {
  jobsEl.textContent = '';
  days[state.day].jobs.forEach(([s, l], i) => {
    const j = doc.createElement('div');
    j.className = 'bkq-booking-job';
    j.style.setProperty('--s', s); j.style.setProperty('--d', l); j.style.setProperty('--i', i);
    if (s === LUNCH[0]) j.dataset.lunch = ''; else j.textContent = l >= 60 ? 'Booked' : '';
    jobsEl.append(j);
  });
}

// ---- start times, re-flowed with FLIP so surviving chips glide to their new places ----
const chips = new Map();
function chip(s) {
  const lab = doc.createElement('label');
  lab.className = 'bkq-booking-slot';
  lab.innerHTML = '<input type="radio"><span></span>';
  const inp = lab.querySelector('input');
  inp.name = 'bkq-booking-t-' + uid; inp.value = s;
  lab.querySelector('span').textContent = hm(s);
  const show = () => { clip(ghost, s, dur()); ghost.dataset.on = ''; };
  const hide = () => { delete ghost.dataset.on; };
  lab.addEventListener('pointerenter', show); lab.addEventListener('pointerleave', hide);
  inp.addEventListener('focus', show); inp.addEventListener('blur', hide);
  inp.addEventListener('change', () => { state.start = s; inp.setAttribute('aria-label', hm(s) + ' to ' + hm(s + dur())); summary(); });
  return lab;
}
function renderSlots(animate) {
  const starts = fits(days[state.day].jobs, dur());
  const first = new Map();
  chips.forEach((el, k) => first.set(k, el.getBoundingClientRect()));
  chips.forEach((el, k) => { if (!starts.includes(k)) { el.remove(); chips.delete(k); } });
  let prev = null;
  starts.forEach((s) => {
    let el = chips.get(s);
    if (!el) { el = chip(s); chips.set(s, el); if (prev) prev.after(el); else slotsEl.prepend(el); }
    prev = el;
  });
  if (animate && !reduce.matches) {
    let n = 0;
    chips.forEach((el, k) => {
      const r = el.getBoundingClientRect(), f = first.get(k);
      if (f) {
        const dx = f.left - r.left, dy = f.top - r.top;
        if (dx || dy) el.animate([{ transform: `translate(${dx}px, ${dy}px)` }, { transform: 'none' }], { duration: 520, easing: SPRING });
      } else {
        el.animate([{ opacity: 0, transform: 'scale(.6)' }, { opacity: 1, transform: 'none' }], { duration: 360, delay: 60 + n++ * 28, easing: 'cubic-bezier(.2, .85, .25, 1)', fill: 'backwards' });
      }
    });
  }
  if (state.start !== null && !starts.includes(state.start)) state.start = null;
  chips.forEach((el, k) => { el.querySelector('input').checked = k === state.start; });
  none.hidden = starts.length > 0;
  fitEl.textContent = starts.length + (starts.length === 1 ? ' start time fits' : ' start times fit');
  dayInputs.forEach((d, i) => {
    const n = fits(days[i].jobs, dur()).length;
    d.free.textContent = n ? n + ' free' : 'full';
    d.lab.toggleAttribute('data-full', n === 0);
  });
}

function summary() {
  const price = +state.svc.dataset.price, total = price + (loan.checked ? 10 : 0);
  what.textContent = state.svc.parentElement.querySelector('.bkq-booking-svcn').textContent + ' · ' + dur() + ' min';
  wp.textContent = '£' + price;
  root.style.setProperty('--bkq-booking-total', total);
  tot.setAttribute('aria-label', 'Total £' + total);
  const d = days[state.day].date;
  if (state.start === null) {
    when.textContent = fmt(d, { weekday: 'long', day: 'numeric', month: 'long' }) + ' · pick a start time';
    delete when.dataset.set; delete pick.dataset.on;
  } else {
    when.textContent = fmt(d, { weekday: 'long', day: 'numeric', month: 'long' }) + ' · ' + hm(state.start) + '–' + hm(state.start + dur());
    when.dataset.set = ''; clip(pick, state.start, dur()); pick.dataset.on = '';
  }
  go.disabled = state.start === null;
}

function update(animate) { drawJobs(); renderSlots(animate); summary(); }

svcInputs.forEach((i) => i.addEventListener('change', () => { state.svc = i; renderSlots(true); summary(); }));
loan.addEventListener('change', summary);

go.addEventListener('click', () => {
  if (state.start === null) return;
  const d = days[state.day].date;
  const ref = 'SW\u2011' + (1000 + ((d.getDate() * 97 + state.start * 7 + dur()) % 9000));
  root.querySelector('.bkq-booking-okt').textContent = what.textContent.split(' · ')[0] + ', ' + fmt(d, { weekday: 'long', day: 'numeric', month: 'long' }) + ', ' +
    hm(state.start) + '–' + hm(state.start + dur()) + '. Ref ' + ref + '. Drop the bike off 15 minutes early; we text you when it’s ready.';
  ok.hidden = false;
  ok.focus({ preventScroll: true });
});
root.querySelector('.bkq-booking-again').addEventListener('click', () => { ok.hidden = true; go.focus({ preventScroll: true }); });
ok.addEventListener('keydown', (e) => { if (e.key === 'Escape') { ok.hidden = true; go.focus({ preventScroll: true }); } });

update(false);

