.bkq-longread {
  /* re-theme with these four */
  --bkq-longread-bg: oklch(23.5% 0.055 18);
  --bkq-longread-ink: oklch(93% 0.025 80);
  --bkq-longread-accent: oklch(82% 0.075 155);
  --bkq-longread-paper: oklch(27% 0.06 18);

  --bkq-longread-muted: color-mix(in oklch, var(--bkq-longread-ink) 66%, var(--bkq-longread-bg));
  --bkq-longread-faint: color-mix(in oklch, var(--bkq-longread-ink) 36%, var(--bkq-longread-bg));
  --bkq-longread-line: color-mix(in oklch, var(--bkq-longread-ink) 14%, var(--bkq-longread-bg));
  --bkq-longread-serif: ui-serif, "Iowan Old Style", "Palatino Linotype", Palatino, Georgia, serif;
  --bkq-longread-out: cubic-bezier(.16, 1, .3, 1);
  --bkq-longread-gutter: clamp(16px, 5cqi, 72px);

  container-type: inline-size;
  container-name: bkq-longread;
  timeline-scope: --bkq-longread-t1, --bkq-longread-t2, --bkq-longread-t3, --bkq-longread-t4, --bkq-longread-t5, --bkq-longread-t6, --bkq-longread-t7, --bkq-longread-t8, --bkq-longread-sc;
  box-sizing: border-box;
  width: 100%;
  background:
    radial-gradient(70cqi 40cqi at 100% 0%, color-mix(in oklch, var(--bkq-longread-ink) 6%, transparent), transparent 70%),
    var(--bkq-longread-bg);
  color: var(--bkq-longread-ink);
  font: 400 15.5px/1.6 system-ui, -apple-system, "Segoe UI", Roboto, sans-serif;
  -webkit-font-smoothing: antialiased;

  & *, & *::before, & *::after { box-sizing: border-box; }
  & :where(h2, h3, p, ol) { margin: 0; padding: 0; }
  & button { font: inherit; color: inherit; }
  & :focus-visible { outline: 1.5px solid var(--bkq-longread-accent); outline-offset: 3px; border-radius: 4px; }
}

.bkq-longread-in {
  display: grid;
  gap: 24px;
  grid-template-columns: minmax(0, 1fr);
  grid-template-areas: "head" "nav" "frame";
  padding: clamp(40px, 6cqi, 84px) var(--bkq-longread-gutter);
  max-width: 1280px;
  margin-inline: auto;
}

.bkq-longread-head { grid-area: head; display: grid; gap: 14px; }
.bkq-longread-brand {
  display: flex; flex-wrap: wrap; align-items: center; gap: 4px 12px;
  font-size: 12px; letter-spacing: .04em; color: var(--bkq-longread-muted);
  & svg { width: 26px; height: 26px; fill: none; stroke: var(--bkq-longread-accent); stroke-width: 1.4; stroke-linejoin: round; }
  & b { font: italic 400 22px/1 var(--bkq-longread-serif); letter-spacing: -.01em; color: var(--bkq-longread-ink); }
}
.bkq-longread-title {
  font: 400 clamp(38px, 5cqi + 14px, 76px)/.95 var(--bkq-longread-serif);
  letter-spacing: -.035em;
  text-wrap: balance;
  & em { font-style: italic; color: var(--bkq-longread-accent); }
}
.bkq-longread-lede { max-width: 40ch; color: var(--bkq-longread-muted); text-wrap: pretty; }

/* ---- index ---- */
.bkq-longread-nav { grid-area: nav; display: grid; gap: 18px; align-content: start; min-width: 0; }
.bkq-longread-index {
  position: relative;
  list-style: none;
  display: grid; grid-auto-flow: column; grid-auto-columns: minmax(150px, 1fr); gap: 0;
  overflow-x: auto; scrollbar-width: none; scroll-snap-type: x proximity;
  scroll-padding-inline: var(--bkq-longread-gutter);
  margin-inline: calc(var(--bkq-longread-gutter) * -1);
  padding-inline: var(--bkq-longread-gutter);
  &::-webkit-scrollbar { display: none; }
  & li { scroll-snap-align: start; }
}
.bkq-longread-ix {
  position: relative;
  width: 100%; height: 100%;
  display: grid; grid-template-columns: auto minmax(0, 1fr); align-items: baseline; gap: 4px 10px;
  padding: 10px 14px 14px 0;
  border: 0; background: none; text-align: left; cursor: pointer;
  color: var(--bkq-longread-muted);
  transition: color .3s;
  &:hover { color: var(--bkq-longread-ink); }
  &[aria-current="true"] { color: var(--bkq-longread-ink); }
}
.bkq-longread-ixn { font: italic 400 15px/1 var(--bkq-longread-serif); color: var(--bkq-longread-faint); font-variant-numeric: tabular-nums; transition: color .3s; .bkq-longread-ix[aria-current="true"] & { color: var(--bkq-longread-accent); } }
.bkq-longread-ixq { font-size: 13.5px; line-height: 1.35; text-wrap: pretty; }
.bkq-longread-rail {
  position: absolute; left: 0; right: 14px; bottom: 4px; height: 2px;
  background: var(--bkq-longread-line);
  overflow: hidden;
  & b { position: absolute; inset: 0; background: var(--bkq-longread-accent); transform-origin: 0 50%; scale: var(--p, 0) 1; }
}
.bkq-longread-cta {
  display: flex; flex-wrap: wrap; align-items: center; justify-content: space-between; gap: 10px 16px;
  padding-top: 16px; border-top: 1px solid var(--bkq-longread-line);
  font-size: 13px; color: var(--bkq-longread-muted);
  & a {
    display: inline-flex; align-items: center; gap: 8px;
    padding: 10px 16px; border-radius: 999px;
    background: var(--bkq-longread-ink); color: var(--bkq-longread-bg);
    font-weight: 600; text-decoration: none;
    transition: background-color .3s, translate .5s var(--bkq-longread-out);
    &:hover { background: var(--bkq-longread-accent); translate: 0 -2px; }
  }
}

/* ---- answers pane ---- */
.bkq-longread-frame {
  grid-area: frame;
  position: relative;
  border-radius: 6px;
  background: var(--bkq-longread-paper);
  border: 1px solid var(--bkq-longread-line);
  overflow: hidden;
  &::after {
    content: ""; position: absolute; left: 0; right: 0; bottom: 0; height: 64px; pointer-events: none;
    background: linear-gradient(transparent, var(--bkq-longread-paper));
  }
}
.bkq-longread-bar {
  position: absolute; left: 0; right: 0; top: 0; height: 3px; z-index: 2;
  & b { position: absolute; inset: 0; background: var(--bkq-longread-accent); transform-origin: 0 50%; scale: var(--bkq-longread-sp, 0) 1; }
}
.bkq-longread-pane {
  position: relative;
  height: 500px;
  overflow-y: auto;
  overscroll-behavior: contain;
  scroll-timeline: --bkq-longread-sc block;
  padding: 28px clamp(20px, 4cqi, 48px) 80px;
  scrollbar-width: thin;
  scrollbar-color: var(--bkq-longread-line) transparent;
  &:focus-visible { outline-offset: -3px; }
}
.bkq-longread-ans {
  position: relative;
  display: grid; grid-template-columns: minmax(0, 1fr); gap: 12px;
  padding: 26px 0 30px;
  scroll-margin-top: 16px;
  & + & { border-top: 1px solid var(--bkq-longread-line); }
  & h3 { font: 400 clamp(23px, 1.4cqi + 16px, 32px)/1.12 var(--bkq-longread-serif); letter-spacing: -.02em; text-wrap: balance; max-width: 22ch; }
  & p { max-width: 58ch; color: color-mix(in oklch, var(--bkq-longread-ink) 84%, var(--bkq-longread-bg)); text-wrap: pretty; }
}
.bkq-longread-num {
  font: italic 400 clamp(54px, 4cqi + 30px, 84px)/.8 var(--bkq-longread-serif);
  letter-spacing: -.04em;
  color: transparent;
  -webkit-text-stroke: 1px color-mix(in oklch, var(--bkq-longread-accent) 70%, var(--bkq-longread-bg));
  font-variant-numeric: tabular-nums;
  transform-origin: 0 100%;
}
.bkq-longread-end { padding: 28px 0 0; border-top: 1px solid var(--bkq-longread-line); font: italic 400 18px/1.5 var(--bkq-longread-serif); color: var(--bkq-longread-muted); max-width: 46ch; }

/* Scroll-driven: each answer is a view timeline, hoisted to the root with timeline-scope so the index can read it. */
@supports (animation-timeline: view()) {
  .bkq-longread-rail b { scale: 0 1; animation: bkq-longread-fill linear both; animation-range: cover 10% cover 90%; }
  .bkq-longread-bar b { scale: 0 1; animation: bkq-longread-fill linear both; animation-timeline: --bkq-longread-sc; }
  .bkq-longread-num { animation: bkq-longread-rise linear both; animation-timeline: view(); animation-range: entry 0% cover 45%; }
  .bkq-longread-ans h3, .bkq-longread-ans p { animation: bkq-longread-ink linear both; animation-timeline: view(); animation-range: entry 0% entry 70%; }
}
@keyframes bkq-longread-fill { from { scale: 0 1; } to { scale: 1 1; } }
@keyframes bkq-longread-rise { from { opacity: .15; transform: translateY(18px) scale(.82); } to { opacity: 1; transform: none; } }
@keyframes bkq-longread-ink { from { opacity: .25; transform: translateY(10px); } to { opacity: 1; transform: none; } }

@container bkq-longread (min-width: 880px) {
  .bkq-longread-in {
    grid-template-columns: minmax(0, 5fr) minmax(0, 7fr);
    grid-template-rows: auto 1fr;
    grid-template-areas: "head frame" "nav frame";
    column-gap: clamp(36px, 6cqi, 96px);
    row-gap: 28px;
  }
  .bkq-longread-index {
    grid-auto-flow: row; grid-auto-columns: auto;
    overflow: visible; margin-inline: 0; padding-inline: 0;
  }
  .bkq-longread-ix { padding: 9px 0 11px; grid-template-columns: 28px minmax(0, 1fr); }
  .bkq-longread-rail { right: 0; bottom: 0; height: 1px; }
  .bkq-longread-ix:hover .bkq-longread-ixq { translate: 4px 0; }
  .bkq-longread-ixq { transition: translate .5s var(--bkq-longread-out); }
  .bkq-longread-frame { align-self: stretch; }
  .bkq-longread-pane { height: 100%; min-height: 560px; max-height: 680px; }
}

@media (prefers-reduced-motion: reduce) {
  .bkq-longread-num, .bkq-longread-ans h3, .bkq-longread-ans p { animation: none !important; opacity: 1; transform: none; }
  .bkq-longread-ixq, .bkq-longread-cta a { transition: none; }
}

