const reduce = matchMedia('(prefers-reduced-motion: reduce)');
const uid = Math.random().toString(36).slice(2, 7);
root.querySelectorAll('[id]').forEach((n) => { n.id += '-' + uid; });
root.querySelectorAll('[aria-labelledby]').forEach((n) => n.setAttribute('aria-labelledby', n.getAttribute('aria-labelledby') + '-' + uid));
if (root.hasAttribute('aria-labelledby')) root.setAttribute('aria-labelledby', root.getAttribute('aria-labelledby') + '-' + uid);

const pane = root.querySelector('.bkq-longread-pane');
const index = root.querySelector('.bkq-longread-index');
const answers = [...root.querySelectorAll('.bkq-longread-ans')];
const links = [...root.querySelectorAll('.bkq-longread-ix')];
const rails = links.map((l) => l.querySelector('.bkq-longread-rail b'));
const native = typeof CSS !== 'undefined' && CSS.supports('animation-timeline: view()');

let current = 0;
function setCurrent(k) {
  if (k === current) return;
  links[current].removeAttribute('aria-current');
  current = k;
  links[k].setAttribute('aria-current', 'true');
  // on narrow layouts the index is a horizontal strip: keep the current entry in view, inside the strip only
  if (index.scrollWidth > index.clientWidth + 2) {
    const li = links[k].parentElement;
    index.scrollTo({ left: li.offsetLeft - 16, behavior: reduce.matches ? 'auto' : 'smooth' });
  }
}

function measure() {
  const top = pane.scrollTop, h = pane.clientHeight;
  // the answer whose top has crossed 35% of the pane is the one being read
  let k = 0;
  answers.forEach((a, i) => { if (a.offsetTop - top <= h * 0.35) k = i; });
  if (top + h >= pane.scrollHeight - 2) k = answers.length - 1;
  setCurrent(k);
  if (native) return;
  // fallback for engines without scroll-driven animations: same ranges, driven from script
  const span = Math.max(1, pane.scrollHeight - h);
  root.style.setProperty('--bkq-longread-sp', (top / span).toFixed(4));
  answers.forEach((a, i) => {
    const p = (top + h - a.offsetTop) / (h + a.offsetHeight);
    rails[i].style.setProperty('--p', Math.max(0, Math.min(1, (p - 0.1) / 0.8)).toFixed(4));
  });
}

let queued = false;
pane.addEventListener('scroll', () => {
  if (queued) return;
  queued = true;
  requestAnimationFrame(() => {
    if (!root.isConnected) return;
    queued = false;
    measure();
  });
}, { passive: true });

links.forEach((l, i) => {
  l.addEventListener('click', () => {
    pane.scrollTo({ top: answers[i].offsetTop - 8, behavior: reduce.matches ? 'auto' : 'smooth' });
    setCurrent(i);
  });
  l.addEventListener('keydown', (e) => {
    let n = null;
    if (e.key === 'ArrowDown' || e.key === 'ArrowRight') n = links[i + 1];
    else if (e.key === 'ArrowUp' || e.key === 'ArrowLeft') n = links[i - 1];
    else if (e.key === 'Home') n = links[0];
    else if (e.key === 'End') n = links[links.length - 1];
    if (n) { e.preventDefault(); n.focus(); }
  });
});

const ro = new ResizeObserver(() => { if (!root.isConnected) { ro.disconnect(); return; } measure(); });
ro.observe(pane);
measure();
